/* Recall items per topic. t = subtopic, k = the key point you should be able to say,
   p = priority (1 must know, 2 good to know, 3 detail), g = section in recall order (R recognise, A assess and investigate, T treat now, C complications and traps, F after and follow-up); items are listed in recall order within a section, s = source: p = the Point of Care page,
   a = ANZCOR 11.9 (Australia), b = both. sg = suggestions you can add. */
window.RECALL = {
"chest-pain": { items: [
{id:"cp2",g:"R",p:1,s:"p",t:"Chest pain: which six causes can kill, and must be excluded first?",k:"Cardiac: ACS, aortic dissection, tamponade\nLung: PE, tension pneumothorax\nGut: oesophageal rupture"},
{id:"cp10",g:"R",p:2,s:"p",t:"Which features of chest pain raise the chance of ACS?",k:"Character: pressure, exertional, eased by rest\nRadiation: both arms (LR about 2.6)\nAlso: sweating, lasting over 20 minutes"},
{id:"cp5",g:"R",p:1,s:"p",t:"Which clues suggest aortic dissection, and what test comes before any antithrombotic?",k:"Clues: sudden tearing pain → back, maximal at onset\nSigns: arm BP difference over 20 mmHg, pulse deficit, new AR murmur\nTest: CT aortogram → before any antithrombotic"},
{id:"cp1",g:"A",p:1,s:"a",t:"Chest pain: what do you do in the first 10 minutes?",k:"Within 10 min of first contact:\nECG → BP in both arms → IV access → troponin → chest X-ray\nST elevation → STEMI pathway\nSuspected ACS → aspirin 300 mg"},
{id:"cp3",g:"A",p:1,s:"a",t:"How does an accelerated troponin rule-out work (ADAPT)?",k:"ADAPT: troponin at 0 and 2 hours + TIMI 0 + no ischaemic ECG changes → rule-out\nFaster option: 1-2 hour high-sensitivity algorithm → per your hospital\nUse a validated protocol, not a guess"},
{id:"cp11",g:"A",p:2,s:"p",t:"Why is a raised troponin not the same as an MI, and what is a type 2 MI?",k:"Injury: troponin above the 99th percentile\nMI: injury + evidence of ischaemia\nType 2 MI: supply and demand mismatch\nLook at the rise and fall"},
{id:"cp4",g:"A",p:1,s:"a",t:"Who counts as low risk for ACS in Australia and needs no further coronary testing?",k:"All of these → no further coronary testing:\nUnder 40, atypical symptoms, no known CAD\nNormal troponin and ECG, symptom-free"},
{id:"cp7",g:"A",p:2,s:"a",t:"Intermediate-risk chest pain: how soon should non-invasive testing happen?",k:"Intermediate risk → non-invasive testing\nIdeal: within 7 days\nAcceptable: up to 14 days"},
{id:"cp13",g:"A",p:3,s:"p",t:"What are the contraindications to a stress test?",k:"Do not stress test in:\nAcute MI or unstable angina\nUncontrolled arrhythmia, PE, dissection\nSevere aortic stenosis\nMyocarditis or pericarditis"},
{id:"cp6",g:"C",p:1,s:"p",t:"Why can't the history rule out ACS, and does a GTN response prove cardiac pain?",k:"History cannot rule out ACS: atypical in women, older people, diabetes\nGTN relief → does not prove cardiac pain"},
{id:"cp8",g:"C",p:2,s:"b",t:"When must you not give GTN?",k:"No GTN if:\nLow BP\nInferior MI with RV involvement → do V4R\nRecent PDE-5 inhibitor → sildenafil 24 hours; tadalafil longer"},
{id:"cp9",g:"T",p:2,s:"a",t:"Chest pain: when do you give oxygen, and what is the target in COPD?",k:"Oxygen only if saturations under 93%\nCOPD → target 88-92%"},
{id:"cp12",g:"T",p:3,s:"p",t:"Which non-cardiac causes of chest pain are common, and how is each treated?",k:"Costochondritis → analgesia\nReflux → PPI\nPill oesophagitis → stop the pill, treat the oesophagitis\nShingles → antiviral\nBiliary colic → ultrasound, LFTs\nPanic → diagnosis of exclusion"}
], sg: [
{id:"cps2",g:"R",p:3,s:"p",t:"What is Boerhaave syndrome: how does it present and what do you do?",k:"Pain after forceful vomiting, sometimes surgical emphysema; CT, nil by mouth, surgical review. (My suggestion.)"},
{id:"cps1",g:"A",p:2,s:"p",t:"What are the five HEART score components, and what are the risk bands?",k:"History, ECG, Age, Risk factors, Troponin, each 0-2. Low (0-3), moderate (4-6), high (7-10). (My suggestion from standard teaching.)"}
]},

"acs-and-mi": { items: [
{id:"mi1",g:"R",p:1,s:"p",t:"What are the ECG criteria for STEMI, including the STEMI equivalents?",k:"ST elevation 1 mm or more in two contiguous leads\nV2-V3: 2 mm in men, 1.5 mm in women\nEquivalents:\nPosterior → ST depression V1-V4\naVR elevation + widespread depression\nNew LBBB + symptoms"},
{id:"mi13",g:"R",p:2,s:"p",t:"Type 1 vs type 2 MI: what causes each, and how do you treat type 2?",k:"Type 1: plaque rupture\nType 2: supply and demand mismatch → sepsis, fast AF, anaemia, PE\nType 2 treatment → treat the cause"},
{id:"mi7",g:"A",p:1,s:"a",t:"NSTEACS: how soon should angiography happen for very high, high and intermediate risk?",k:"Very high risk → angiography within 2 hours\nHigh risk (GRACE over 140, dynamic changes, troponin rise) → within 24 hours\nIntermediate (GRACE 109-140) → within 72 hours"},
{id:"mi6",g:"C",p:1,s:"p",t:"How does an RV infarct present, which lead confirms it, and how do you treat it?",k:"Presents: inferior STEMI + low BP + raised JVP + clear lungs\nConfirm: ST elevation in V4R\nTreat: fluid; avoid GTN"},
{id:"mi8",g:"C",p:1,s:"p",t:"Which mechanical complications follow MI, how do they present, and what do you do?",k:"New murmur + pulmonary oedema or shock → papillary muscle or septal rupture\nSudden tamponade → free wall rupture\nThen: urgent echo → surgery"},
{id:"mi15",g:"C",p:3,s:"p",t:"Low BP after angiography: what are the causes, and what do you do?",k:"Think: bleeding (groin or retroperitoneal), re-infarction, tamponade, arrhythmia\nDo: fluid → ECG → Hb → bedside echo → call cardiology"},
{id:"mi14",g:"C",p:3,s:"p",t:"Pericarditis after MI: what do you give, and what do you avoid?",k:"Give: aspirin + colchicine\nAvoid: other NSAIDs early after MI"},
{id:"mi4",g:"T",p:1,s:"a",t:"Aspirin in ACS: what is the loading dose and the maintenance dose?",k:"Load: 300 mg chewed or dissolved\nThen: 100-150 mg daily"},
{id:"mi5",g:"T",p:1,s:"a",t:"Which P2Y12 inhibitor, at what doses, and when is clopidogrel the choice?",k:"Ticagrelor: 180 mg then 90 mg twice daily\nPrasugrel: 60 mg then 10 mg daily → not if over 75, under 60 kg, prior stroke or TIA\nClopidogrel: 300-600 mg then 75 mg → choice with lysis or oral anticoagulation"},
{id:"mi9",g:"T",p:2,s:"a",t:"ACS anticoagulation: which drugs, and what must you not do?",k:"Unfractionated heparin or enoxaparin (enoxaparin may be preferred)\nDo not switch between them"},
{id:"mi10",g:"T",p:2,s:"a",t:"ACS: when do you give oxygen?",k:"Oxygen only if saturations under 93%"},
{id:"mi2",g:"T",p:1,s:"a",t:"STEMI within 12 hours: when primary PCI, when fibrinolysis?",k:"Within 12 hours:\nPrimary PCI possible within 90 min of first medical contact → PCI\nOtherwise, no contraindication → fibrinolysis"},
{id:"mi3",g:"T",p:1,s:"a",t:"How do you recognise failed lysis, what do you do, and when is angiography after successful lysis?",k:"Failed lysis: ST resolution 50% or less at 60-90 min, or unstable → transfer for rescue PCI\nSuccessful lysis → angiography within 24 hours\n(Victoria: Adult Retrieval Victoria coordinates transfer of critically ill adults and gives phone advice, 1300 36 86 61. Confirm who calls at GV Health.)"},
{id:"mi11",g:"F",p:2,s:"a",t:"What is the secondary prevention after MI?",k:"Aspirin → indefinitely\nDAPT → up to 12 months\nStatin → highest tolerated (LDL under 1.8)\nBeta-blocker → if EF 40% or less\nACE inhibitor → where indicated\nCardiac rehab → for all"},
{id:"mi12",g:"F",p:2,s:"a",t:"ACS in a patient with AF: which antiplatelet goes with the anticoagulant, and how long is triple therapy?",k:"Antiplatelet → clopidogrel, with the oral anticoagulant\nTriple therapy → keep it short"}
], sg: [
{id:"mis1",g:"T",p:2,s:"p",t:"What are the contraindications to fibrinolysis?",k:"Any prior intracranial haemorrhage, ischaemic stroke within 3 months, active bleeding, suspected dissection, recent head trauma or neurosurgery. (My suggestion from standard teaching; check your protocol.)"},
{id:"mis2",g:"F",p:3,s:"p",t:"When is CABG chosen over PCI?",k:"Left main, three-vessel, or two-vessel disease including the proximal LAD."}
]},

"pericarditis": { items: [
{id:"pc12",g:"R",p:3,s:"p",t:"What is the commonest cause of pericarditis, and what is its usual course?",k:"Cause: viral (coxsackie B)\nCourse: usually self-limiting"},
{id:"pc1",g:"R",p:1,s:"p",t:"Pericarditis: what are the four diagnostic criteria (two needed)?",k:"Two of four:\nPleuritic pain, better leaning forward\nFriction rub\nWidespread concave ST elevation + PR depression\nNew or worse effusion\n(ESC criteria)"},
{id:"pc2",g:"R",p:1,s:"p",t:"On ECG, how do you tell pericarditis from STEMI, and what if in doubt?",k:"Pericarditis: widespread, concave, PR depression, reciprocal change only in aVR\nSTEMI: territorial, reciprocal depression, Q waves\nIn doubt → treat as STEMI"},
{id:"pc10",g:"R",p:2,s:"p",t:"What are the four ECG stages of pericarditis?",k:"1 → ST elevation\n2 → back to baseline in about a week\n3 → T inversion\n4 → normal over weeks to months"},
{id:"pc3",g:"A",p:1,s:"p",t:"Pericarditis: which high-risk features mean admission?",k:"Admit if any:\nFever, high white cells\nEffusion over 2 cm, tamponade signs\nRaised troponin\nImmunocompromised, anticoagulated, trauma\nNSAID failure"},
{id:"pc6",g:"C",p:1,s:"p",t:"Early post-MI pericarditis: what do you give, and what do you avoid?",k:"Give: aspirin + colchicine\nAvoid: other NSAIDs and steroids early after MI"},
{id:"pc11",g:"C",p:2,s:"p",t:"What is Dressler syndrome, and when does it occur?",k:"Autoimmune pericarditis\nWeeks to months after MI or cardiac surgery"},
{id:"pc5",g:"T",p:1,s:"b",t:"Pericarditis: which NSAID, what dose, how long, and when aspirin instead?",k:"Ibuprofen with food at the lowest effective dose\nAustralian review: 400 mg three times daily; US page: 600-800 mg\nTaper once symptoms and CRP settle\nAfter MI or with CAD → aspirin instead"},
{id:"pc4",g:"T",p:1,s:"a",t:"Pericarditis: what colchicine dose, for how long, and what does it do?",k:"0.5 mg twice daily for 3 months\nAustralian tablets are 0.5 mg → once daily if under 70 kg\nEffect: halves recurrence"},
{id:"pc9",g:"T",p:2,s:"a",t:"Pericarditis on NSAIDs: who needs PPI cover?",k:"PPI cover if:\nOver 65, previous ulcer\nOn aspirin, steroids or anticoagulants"},
{id:"pc7",g:"T",p:2,s:"p",t:"Pericarditis: when are steroids used, what is their downside, and when never?",k:"Second line: NSAID failure or contraindication, autoimmune, uraemic\nDownside: increase recurrence\nNever in bacterial pericarditis"},
{id:"pc8",g:"F",p:2,s:"a",t:"After pericarditis: when can they return to exercise and competitive sport?",k:"No strenuous exercise until symptoms resolve and ECG and CRP normalise\nCompetitive athletes → at least 3 months"}
], sg: [
{id:"pcs2",g:"C",p:3,s:"p",t:"What is myopericarditis, and how is its management different?",k:"Pericarditis with raised troponin: admit, echo, cardiology, longer exercise restriction."},
{id:"pcs1",g:"T",p:2,s:"p",t:"Which drugs interact with colchicine, and when do you reduce the dose?",k:"Clarithromycin, some azoles, verapamil, ciclosporin; reduce in kidney impairment. (My suggestion from standard teaching.)"}
]},

"pericardial-effusion-and-tamponade": { items: [
{id:"tm1",g:"R",p:1,s:"p",t:"Tamponade: why does the speed of fluid collection matter more than its size?",k:"Speed matters more than size\nSmall effusion that collects fast (after a procedure) → can cause tamponade\nLarge effusion that collects slowly → may not"},
{id:"tm2",g:"R",p:1,s:"p",t:"Which signs of tamponade are most useful, and which are late?",k:"Useful: breathlessness, tachycardia, raised JVP, pulsus paradoxus over 10 mmHg\nLate and insensitive: low BP, Beck triad"},
{id:"tm7",g:"R",p:2,s:"p",t:"How do you measure pulsus paradoxus with a cuff, and what value is significant?",k:"Cuff up → pressure where sounds appear only in expiration\nminus pressure where heard throughout\nOver 10 mmHg → pulsus paradoxus\nUnder 10 mmHg → tamponade very unlikely"},
{id:"tm11",g:"R",p:3,s:"p",t:"Tamponade: what do the ECG and chest X-ray show?",k:"ECG: electrical alternans (16-21%), low voltage\nX-ray: big globular heart"},
{id:"tm3",g:"A",p:1,s:"p",t:"What are the echo signs of tamponade?",k:"Effusion\nRV diastolic collapse\nRA systolic collapse\nPlethoric IVC\nSwinging heart"},
{id:"tm8",g:"A",p:2,s:"p",t:"What are the causes of pericardial effusion?",k:"Procedures, pericarditis\nCancer: lung, breast, lymphoma\nUraemia, hypothyroidism\nAutoimmune, radiation, blood"},
{id:"tm9",g:"A",p:2,s:"p",t:"Which tests do you send on pericardial fluid?",k:"Cell count, protein, LDH\nGram stain and culture\nTB tests, cytology"},
{id:"tm10",g:"C",p:2,s:"p",t:"After cardiac surgery: what suggests clot tamponade, and what do you do?",k:"Drains suddenly stop + BP falls + CVP rises → clot tamponade\nCall the surgeon → re-opening may be needed"},
{id:"tm4",g:"T",p:1,s:"p",t:"What is the definitive treatment for tamponade?",k:"Pericardiocentesis\nDo not delay it in an unstable patient"},
{id:"tm5",g:"T",p:1,s:"p",t:"Tamponade: which treatments must you avoid, and why is intubation risky?",k:"Avoid: diuretics, vasodilators\nAvoid intubation if at all possible → positive pressure lowers venous return"},
{id:"tm6",g:"T",p:1,s:"p",t:"Haemopericardium from dissection, free wall rupture or trauma: who fixes it?",k:"Dissection, free wall rupture or trauma → cardiothoracic surgery\nNot just a needle\n(Victoria: Adult Retrieval Victoria coordinates transfer of critically ill adults and gives phone advice, 1300 36 86 61. Confirm who calls at GV Health.)"}
], sg: [
{id:"tms1",g:"F",p:2,s:"p",t:"Recurrent malignant effusion: what is the option?",k:"Consider a pericardial window, matched to goals of care."}
]},

"hypertensive-urgency-and-emergency": { items: [
{id:"ht1",g:"R",p:1,s:"p",t:"Hypertensive urgency vs emergency: what BP, and what separates them?",k:"Both: usually over 180/120\nEmergency: organ damage → brain, eyes, heart, aorta, kidneys, blood\nUrgency: no organ damage → mild headache allowed"},
{id:"ht7",g:"R",p:1,s:"p",t:"High BP in pregnancy over 20 weeks or postpartum: what do you assume, and who do you call?",k:"High BP over 20 weeks or postpartum → pre-eclampsia until proven otherwise\nCall obstetrics"},
{id:"ht2",g:"A",p:1,s:"p",t:"The ward call for high BP: what do you do?",k:"See the patient → re-measure properly → look for organ damage\nTreat: pain, retention, anxiety, missed tablets\nWell patient → no IV drugs"},
{id:"ht8",g:"A",p:2,s:"p",t:"Hypertensive emergency: what is the organ-damage work-up?",k:"ECG, troponin, creatinine, urinalysis\nFBC and film (MAHA)\nChest X-ray, fundoscopy\nCT head if neurological\nCT aortogram if dissection suspected"},
{id:"ht12",g:"C",p:3,s:"p",t:"What is PRES: how does it present, and where does the MRI show change?",k:"PRES presents: headache, seizures, confusion, visual loss\nMRI → parieto-occipital oedema"},
{id:"ht3",g:"T",p:1,s:"p",t:"Hypertensive emergency: how fast do you lower BP, and why not faster?",k:"First hour: no more than 25% fall\nThen about 160/100 over 2-5 hours\nThen normal over days\nToo fast → stroke, kidney injury"},
{id:"ht9",g:"T",p:2,s:"p",t:"Hypertensive urgency: what are the BP targets and the plan?",k:"Under 160/100 over hours\nThen under 130/90 over days\nOral drugs + GP follow-up"},
{id:"ht10",g:"T",p:2,s:"p",t:"Hypertensive emergency: which IV drugs, and what caution for each?",k:"Labetalol → bolus or infusion\nGTN → infusion\nHydralazine → unpredictable\nNicardipine → not stocked everywhere in Australia; check your formulary"},
{id:"ht4",g:"T",p:1,s:"p",t:"Dissection: which drug first, what targets, and what must you never give alone?",k:"First: beta-blocker (labetalol or esmolol)\nTargets within an hour: systolic under 120, heart rate under 60\nNever a vasodilator alone"},
{id:"ht5",g:"T",p:1,s:"p",t:"Hypertension with ACS or pulmonary oedema: which drug, what target, and which drug to avoid?",k:"Drug: GTN\nTarget: systolic under 140 within an hour\nAvoid beta-blockers in pulmonary oedema or shock"},
{id:"ht6",g:"T",p:1,s:"p",t:"Stimulant toxicity with high BP: what first, what to avoid, and who to call?",k:"First: benzodiazepines\nAvoid: a beta-blocker alone\nCall: Poisons Information Centre 13 11 26"},
{id:"ht11",g:"F",p:2,s:"p",t:"What are the secondary causes of hypertension?",k:"Drugs: NSAIDs, steroids, pill, stimulants\nSleep apnoea\nRenal artery stenosis\nPrimary aldosteronism, phaeochromocytoma\nThyroid, Cushing, coarctation"}
], sg: [
{id:"hts1",g:"C",p:2,s:"p",t:"Why not give sublingual nifedipine?",k:"Unpredictable, sometimes severe BP drops. (My suggestion from standard teaching.)"}
]},

"syncope-and-loss-of-consciousness": { items: [
{id:"sy1",g:"R",p:1,s:"p",t:"What is syncope, and which mimics must you exclude first?",k:"Syncope: brief LOC from low brain blood flow → fast full recovery\nExclude first: hypoglycaemia, hypoxia, intoxication, seizure, stroke"},
{id:"sy4",g:"R",p:1,s:"p",t:"What are the three kinds of syncope, how common is each, and what if unclear?",k:"Reflex: about 60%\nOrthostatic: 15%\nCardiac: 15%\nIf reflex or orthostatic is not clear → think cardiac"},
{id:"sy11",g:"R",p:3,s:"p",t:"Seizure vs syncope: which feature points to seizure, and which don't help?",k:"Points to seizure: prolonged confusion afterwards\nDoes not help: tongue biting and incontinence (occur in both)"},
{id:"sy2",g:"A",p:1,s:"p",t:"What are the red flags for cardiac syncope (including the family history)?",k:"Exertional or supine, no warning\nPalpitations, chest pain, breathlessness\nHeart disease, abnormal ECG\nFamily history of sudden death"},
{id:"sy-h1",g:"A",p:1,s:"p",from:["h1794306715277"],t:"What are the can't-miss causes of syncope?",k:"Arrhythmia, aortic stenosis, PE\nBleeding: GI bleed, ruptured AAA, ectopic pregnancy\nSeizure, stroke"},
{id:"sy3",g:"A",p:1,s:"p",t:"Syncope: what do you look for on the ECG?",k:"Heart block or pauses\nLong QT, delta wave (WPW)\nBrugada, HCM voltages, ARVC epsilon wave\nIschaemia, new arrhythmia"},
{id:"sy6",g:"A",p:1,s:"p",t:"How do you do lying and standing BP, and what fall is orthostatic hypotension?",k:"Measure: lying → immediately on standing → at 3 minutes\nOrthostatic hypotension: fall of 20 systolic or 10 diastolic"},
{id:"sy7",g:"A",p:2,s:"p",t:"Syncope: which tests does everyone get?",k:"Everyone: ECG, glucose, FBC, electrolytes, troponin\nAdmitted → telemetry\nWomen of child-bearing age → pregnancy test"},
{id:"sy8",g:"A",p:2,s:"p",t:"Syncope: when do you order an echo, when a CT head, and is carotid Doppler useful?",k:"Echo → murmur, heart disease or abnormal ECG\nCT head → head strike with anticoagulants, or focal signs\nCarotid Doppler → rarely helps"},
{id:"sy9",g:"A",p:2,s:"p",t:"What are the causes of orthostatic hypotension?",k:"Drugs: diuretics, vasodilators, alpha-blockers, beta-blockers\nDehydration\nAutonomic failure: Parkinson disease, diabetes, amyloid"},
{id:"sy10",g:"T",p:2,s:"p",t:"How do you treat reflex, orthostatic and cardiac syncope?",k:"Reflex → education, counter-pressure\nOrthostatic → stop culprit drugs, fluids, stockings → midodrine or fludrocortisone by specialist\nCardiac → treat the cause"},
{id:"sy5",g:"F",p:1,s:"a",t:"Syncope and private driving (Austroads): what are the rules?",k:"Typical vasovagal, unlikely while driving → fit\nSingle blackout, uncertain cause → 6 months\nTwo or more, over 24 hours apart → 12 months\nLicensing authority decides (Austroads)"}
], sg: [
{id:"sys1",g:"R",p:2,s:"p",t:"Which bleeding causes can present as syncope?",k:"Melaena, ruptured AAA, ectopic pregnancy can present as syncope. (My suggestion.)"}
]},

"acute-decompensated-heart-failure": { items: [
{id:"hf3",g:"R",p:1,s:"p",t:"ADHF: what do you do for warm-wet, warm-dry, cold-wet and cold-dry?",k:"Warm + wet → IV diuretic (most common)\nWarm + dry → look for another cause\nCold + wet → shock → ICU\nCold + dry → senior review, stop diuretics, consider cautious fluid"},
{id:"hf1",g:"R",p:1,s:"b",t:"How do you spot cardiogenic shock, and what do you do straight away?",k:"Spot it: systolic under 90 for over 30 min, cold and clammy, narrow pulse pressure, confusion, rising lactate, poor urine\nStraight away: call senior and ICU → stop the beta-blocker and vasodilators\n(Victoria: Adult Retrieval Victoria coordinates transfer of critically ill adults and gives phone advice, 1300 36 86 61. Confirm who calls at GV Health.)"},
{id:"hf14",g:"R",p:2,s:"p",t:"ADHF: what NT-proBNP rules it out, and which exam and X-ray findings are most useful?",k:"NT-proBNP under 300 → ADHF unlikely\nBest signs: S3 (LR 11), JVP (LR 5)\nCrackles are not specific\nCXR oedema → LR 12"},
{id:"hf9",g:"A",p:1,s:"p",t:"What are the common triggers of decompensated heart failure?",k:"Salt, fluid, missed tablets\nIschaemia, arrhythmia (AF), hypertension\nDrugs: NSAIDs, steroids, verapamil or diltiazem\nInfection, kidney injury\nAlcohol or cocaine, valve disease\nIatrogenic IV fluid"},
{id:"hf6",g:"C",p:1,s:"p",t:"Creatinine rising during diuresis: what does it usually mean, what do you do, and which two blood results tell you diuresis is going well?",k:"Usually haemodynamic, not kidney damage\nLess fluid in the circulation → kidney filters at slightly lower pressure → creatinine creeps up\nStill congested → keep diuresing, trust the exam\nGoing well (sweet spot): bicarbonate rising + creatinine stable or only a little up\nWhy: salt water leaves → bicarbonate left behind is more concentrated (contraction alkalosis)\nWorry: creatinine keeps climbing while they look dry, BP falls, or urine output drops → discuss with your senior"},
{id:"hf10",g:"C",p:2,s:"p",from:["h1794380007689"],t:"Diuretic resistance on furosemide 80 mg IV twice daily: what are the next steps, and why check K before acetazolamide?",k:"Not enough urine on furosemide 80 mg IV twice daily:\nCall cardiology\nThen: furosemide infusion, or add thiazide (metolazone), or add acetazolamide if alkalotic and K above 4 (ADVOR)\nCheck K first → acetazolamide wastes potassium like the loops\nNot verified: the K above 4 cut-off is from the Point of Care page, not checked against the Australian Diamox product information. Confirm with your hospital protocol."},
{id:"hf11",g:"C",p:2,s:"p",dup:"hfd5",t:"Potassium and magnesium",k:"Check daily, replace early → loop diuretics waste both\nKeep spironolactone going to hold potassium"},
{id:"hf8",g:"C",p:1,s:"a",from:["h1794380073094"],t:"In hospital, when do you hold or reduce ARNI, ACE inhibitor, ARB, MRA and beta-blocker?",k:"ARNI, ACE inhibitor, ARB or MRA:\nCaution → systolic under 95, K over 5.0, eGFR under 20\nReduce → K 5.5-6.0\nWithhold → K over 6.0\nBeta-blocker: caution → HR under 55 or systolic under 95"},
{id:"hf2",g:"T",p:1,s:"b",t:"Acute pulmonary oedema: what are the first steps, and what do you avoid?",k:"Sit up → oxygen if hypoxic\nCPAP or NIV if oxygen not enough or CO2 rises\nGTN if BP allows → infusion from about 5-10 mcg/min\nIV furosemide\nAvoid morphine"},
{id:"hf4",g:"T",p:1,s:"p",t:"ADHF: what starting dose of IV loop diuretic?",k:"About twice the home oral dose, given IV (higher with kidney disease)\nAustralian ED handbook: furosemide 80 mg IV, or the usual dose IV"},
{id:"hf5",g:"T",p:1,s:"p",t:"After the first IV diuretic dose: what do you check at 1 hour and at 3-4 hours, and what do you do?",k:"1 hour: urine → none, check for shock and double the dose\n3-4 hours: less than halfway to goal → double; otherwise repeat\nSecond dose by early afternoon"},
{id:"hf7",g:"T",p:1,s:"a",t:"What are the four pillars for HFrEF, and when do you start them?",k:"ARNI preferred → or ACE inhibitor (36-hour washout before ARNI); ARB last-line\nBeta-blocker → bisoprolol, carvedilol, metoprolol succinate, nebivolol\nMRA\nSGLT2 inhibitor → dapagliflozin or empagliflozin\nStart all as soon as clinically possible"},
{id:"hf12",g:"F",p:2,s:"a",t:"Heart failure: what are the IV iron criteria, which iron, and why not oral?",k:"Ferritin under 100 µg/L, or 100-299 with TSAT under 20%\n→ IV ferric carboxymaltose\nOral iron does not work in heart failure"},
{id:"hf13",g:"F",p:2,s:"a",t:"ADHF: what is the discharge plan?",k:"Oral diuretic when symptoms and JVP improve → ideally tested for 24 hours\nDaily weights → 2 kg change in 2 days → contact GP within 24 hours\nReview within 1-2 weeks\nUptitrate the pillars at least twice before discharge"},
{id:"hf15",g:"F",p:3,s:"p",t:"Heart failure devices: how long after full medical therapy, and who gets an ICD or CRT?",k:"After 3-6 months of full therapy:\nICD → EF under 35% (US criteria)\nCRT → EF under 35% with QRS over 150 ms, especially LBBB\nCardiology decides"},
{id:"hf-h1",g:"F",p:2,s:"n",from:["h1794380776669"],t:"Why does CRT help most when the QRS is very wide with LBBB, and less with RBBB?",k:"LBBB → left ventricle activated late → ventricles squeeze out of step → pump wastes effort\nWider QRS → bigger delay\nCRT paces the right ventricle and the late left lateral wall (lead through the coronary sinus) together → fixes that delay\nRBBB or non-specific delay → late part is elsewhere or scattered → pacing the left wall helps less\nCut-offs (QRS 150 ms or more, EF 35% or less, sinus rhythm, full therapy) are on the card above; cardiology decides\n(Mechanism is standard teaching; the Australian 2018 heart failure guideline could not be opened this run to confirm the exact cut-offs.)"},
{id:"hfd1",g:"T",p:2,s:"n",t:"Where does each diuretic class act, and how much sodium is taken back at each site?",k:"Proximal tubule → acetazolamide (about 65% of sodium taken back)\nThick limb of the loop → loop diuretics (about 25%, the strongest)\nDistal tubule → thiazides (about 5%)\nCollecting duct → spironolactone (about 3-5%)\nBlock one part → later parts take back more\n(Percentages are standard physiology, not from an Australian source.)"},
{id:"hfd2",g:"T",p:1,s:"n",t:"Why give furosemide IV in congestion, and how fast can you push it?",k:"Oral: absorption unpredictable (Australian product information: mean about 60% in healthy men, wide spread) and a swollen gut absorbs less\nIV: starts in about 5 min; oral about 1 hour\nSteep dose-response → below a threshold dose nothing happens; kidney disease raises the threshold\nIV rate: no faster than 4 mg/minute (hearing)"},
{id:"hfd3",g:"T",p:2,s:"n",t:"Furosemide, bumetanide and torasemide: how long do they last, how do doses compare, and what is available in Australia?",k:"Furosemide: half-life up to about 100 min (longer in kidney or liver disease) → oral lasts 6-8 hours, IV about 2 hours\nBumetanide: absorbed almost completely, half-life about 1 hour (your notes)\nDose: about 1 mg bumetanide = 40 mg oral furosemide; oral furosemide about half as potent as IV (standard teaching)\nBumetanide: registered in Australia (Burinex), not PBS-listed for heart failure\nTorasemide: half-life about 3-6 hours, once daily (your notes) → could not confirm it is marketed in Australia; check your hospital"},
{id:"hfd4",g:"T",p:2,s:"n",t:"Thiazides in heart failure: how strong are they, when do they work poorly, and when are they used?",k:"Site: distal tubule → weaker than loops, poor at low GFR\nUse: add-on for diuretic resistance, not routine\nMedicine Today July 2026: hydrochlorothiazide 12.5-25 mg daily; metolazone not PBS-listed for heart failure\nChlorthalidone (Hygroton): in the Australian medicines listing, availability not confirmed → check your hospital protocol"},
{id:"hfd5",g:"C",p:1,s:"n",t:"Which electrolytes do loop diuretics waste, what acid-base change follows, and how do you protect against it?",k:"Lose: sodium, potassium, chloride, calcium, magnesium, hydrogen\nResult: low K and Mg + contraction alkalosis\nThey do not retain potassium or hydrogen\nProtect: check K and Mg daily → replace early → keep spironolactone going to hold potassium"},
{id:"hfd6",g:"C",p:1,s:"n",from:["h1794378706339","h1794378710046"],t:"Thiazides vs spironolactone: what does each do to potassium, acid-base and sodium?",k:"Thiazides → lose potassium and hydrogen → low K, alkalosis\nThiazides → classic drug cause of hyponatraemia; keep calcium (useful in calcium stones)\nSpironolactone → blocks aldosterone → keeps potassium and hydrogen → high K, metabolic acidosis; can add to low sodium\nSpironolactone improves survival in HFrEF → check K and creatinine"},
{id:"hfd7",g:"C",p:2,s:"n",from:["h1794378583887"],t:"Acetazolamide: how does it work, what acid-base change does it cause, and when is it added in heart failure?",k:"Blocks carbonic anhydrase in the proximal tubule → loses bicarbonate and sodium → metabolic acidosis\nIn heart failure: add-on when loops are not enough (ADVOR), especially if alkalotic\nNot a starter\nMedicine Today: 250-500 mg daily"},
{id:"hfd8",g:"C",p:1,s:"n",from:["h1794378605510"],t:"Why do diuretics stop working, and what is the fix for each reason?",k:"Braking: drug wears off, kidney grabs sodium back → doses more often or an infusion\nDownstream catch-up: later segments take back more → add a second class (thiazide, spironolactone or acetazolamide)\nPoor gut absorption → give IV\nPoor kidney function → higher threshold dose\nAcetazolamide is not the long-acting fix for braking; it is a second site of action"}
], sg: [
{id:"hfs1",g:"R",p:2,s:"p",t:"What are the EF cut-offs for HFrEF, HFmrEF and HFpEF, and where are the pillars proven?",k:"EF 40% or less, 41-49%, and 50% or more. The four pillars are proven in HFrEF; empagliflozin should also be considered in HFmrEF and HFpEF."},
{id:"hfs2",g:"A",p:2,s:"p",t:"New heart failure: what is the work-up for ischaemic and non-ischaemic causes?",k:"Ischaemic: ECG, troponin, stress test or angiogram. Non-ischaemic: lipids, HbA1c, iron studies, TSH, and others by suspicion; cardiac MRI if unclear."},
]},

"aortic-dissection": { items: [
{id:"ad3",g:"R",p:1,s:"p",t:"How does aortic dissection present, and what are the can't-miss signs?",k:"Tearing chest or back pain\nAortic regurgitation murmur\nPulse deficit\nArm BP difference over 20 mmHg"},
{id:"ad9",g:"R",p:2,s:"p",t:"What are the risk factors for aortic dissection, and what do you think of under 40?",k:"Hypertension (about 70%)\nUnder 40 → think Marfan, connective tissue disease, bicuspid valve\nAlso: smoking, family history"},
{id:"ad1",g:"R",p:1,s:"p",t:"Type A vs type B dissection: what is involved, and what does each need?",k:"Type A: involves ascending aorta → urgent surgical repair\nType B: descending only → usually medical; TEVAR if complicated"},
{id:"ad10",g:"A",p:2,s:"p",t:"Aortic dissection: what is the first-hour work-up?",k:"Telemetry\nBloods: FBC, UEC, coags, troponin, D-dimer, group and hold\nTests: ECG, CXR, CT aortogram, echo\nSerial BP in both arms; consider an arterial line"},
{id:"ad4",g:"A",p:1,s:"p",t:"Aortic dissection: which test is best, and what can D-dimer, CXR and ECG not do?",k:"Best test: CTA (most sensitive and specific)\nD-dimer: high negative predictive value, cannot fully rule it out\nCXR: widened mediastinum in about a third\nECG: often normal"},
{id:"ad7",g:"C",p:2,s:"p",t:"What are the complications of type A dissection?",k:"Coronaries → MI\nAortic valve → regurgitation\nCarotids → stroke\nTamponade"},
{id:"ad8",g:"C",p:2,s:"p",t:"Complicated type B dissection: which branch vessels are affected, how does each present, and what is needed?",k:"Renal → oliguria, failure\nMesenteric (celiac) → gut ischaemia\nSpinal → leg weakness, paraplegia\nDistal occlusion (Leriche)\nAll need TEVAR"},
{id:"ad5",g:"T",p:1,s:"p",t:"Aortic dissection: who do you call, and when do you involve haematology?",k:"Call: cardiothoracic surgery urgently\nHaematology early if on anticoagulation → reversal may be needed\n(Victoria: Adult Retrieval Victoria coordinates transfer of critically ill adults and gives phone advice, 1300 36 86 61. Confirm who calls at GV Health.)"},
{id:"ad12",g:"T",p:3,s:"p",t:"Aortic dissection: how do you control the pain?",k:"IV morphine\nThe page gives no dose → use your protocol"},
{id:"ad2",g:"T",p:1,s:"p",t:"Aortic dissection: what HR and BP targets, which drug first, and what must you never do?",k:"Targets: HR under 60, SBP 100-120\nFirst: IV labetalol or esmolol\nSBP still over 120 → add nitroprusside or nicardipine\nNever a vasodilator without a beta-blocker → reflex tachycardia raises wall stress"},
{id:"ad6",g:"T",p:1,s:"p",t:"Low BP in aortic dissection: what do you give, what do you avoid, and what do you think of?",k:"Give: fluids + noradrenaline\nAvoid: inotropes\nThink: tamponade"},
{id:"ad11",g:"F",p:2,s:"p",t:"After aortic dissection: what are the discharge and long-term measures?",k:"Statin, beta-blocker, low-dose aspirin\nStop smoking, control BP, avoid straining"},
{id:"ad14",g:"F",p:3,s:"p",t:"Aortic aneurysm: what size or growth means surgery, and how is it different in women?",k:"Surgery if: over 5.5 cm, or growth over 0.5 cm in 6 months, or over 1 cm in a year\nWomen: lower threshold (4.5-5 cm, debated)"},
{id:"ad13",g:"F",p:3,s:"p",t:"Aortic dissection: what is the mortality for type A with and without surgery, and for type B?",k:"Type A: surgery 26% mortality vs over 50% medical (IRAD 2000)\nType B: 9% in hospital, 20% at 5 years"}
], sg: [
{id:"ads3",g:"R",p:3,s:"p",t:"What are DeBakey types 1, 2 and 3?",k:"1 ascending and descending, 2 ascending only, 3 descending only."},
{id:"ads2",g:"A",p:2,s:"p",t:"What does the aortic dissection risk score (ADD-RS) count, and what is it used for?",k:"Counts high-risk conditions, high-risk pain features and high-risk exam findings (0-3 points). Used to decide between D-dimer and straight to CTA. (My suggestion.)"},
{id:"ads1",g:"C",p:2,s:"p",t:"Possible dissection: why must you not give an anticoagulant or thrombolytic?",k:"They can extend the bleed. Rule dissection out before giving them to a patient with tearing pain. (My suggestion from standard teaching, not on the page.)"}
]},

"pulmonary-embolism-and-vte": { items: [
{id:"pe12",g:"R",p:2,s:"p",t:"PE risk factors: which are strong, moderate and weak, and what is Virchow's triad?",k:"Strong (OR over 10): fracture or major surgery\nModerate (OR 2-9): OCP, hospitalised, previous VTE, cancer, sepsis\nWeak (OR under 2): bed rest, long travel, age, obesity, smoking, cirrhosis, CKD\nVirchow: stasis, vessel injury, hypercoagulability"},
{id:"pe11",g:"R",p:2,s:"p",t:"Massive PE: why does the heart fail, and which arrest does it cause?",k:"RV pressure rises → cardiac output falls → SVR rises\nSeptum bows into the LV → cuts filling further\nCommon cause of PEA arrest"},
{id:"pe6",g:"A",p:1,s:"p",t:"PE rule-out: how do PERC, D-dimer and imaging fit by probability, and what are the D-dimer cut-offs?",k:"Low probability → PERC or D-dimer\nModerate or high → imaging\nD-dimer under 500 with moderate probability, or under 1000 with low probability → rules out\nAge-adjusted cut-off: age x 10"},
{id:"pe10",g:"A",p:2,s:"p",t:"PE: what does the ECG show, and how often?",k:"Normal in 20%\nTachycardia is commonest (28%)\nT-wave inversion V1-V4\nS1Q3T3 (about 8%), new RBBB\nST elevation in aVR"},
{id:"pe9",g:"A",p:2,s:"p",t:"PE: what are the signs of RV strain on echo, CT and bloods?",k:"Echo: enlarged RV, moderate or severe TR, McConnell's sign, flat septum\nCT: RV/LV over 0.9\nBloods: troponin up, NT-proBNP over 500"},
{id:"pe1",g:"A",p:1,s:"p",t:"PE: what are the three risk classes, and what defines each?",k:"High: arrest or SBP under 90 not from another cause (PESI IV+)\nIntermediate: RV strain or troponin, no hypotension → high if both, low if only one\nLow: neither"},
{id:"pe14",g:"C",p:3,s:"p",t:"PE special situations: cancer, malabsorption or obesity, subsegmental PE, and a negative leg Doppler?",k:"Cancer → LMWH beats warfarin (CLOT)\nMalabsorption or BMI over 40 → DOACs less reliable\nSubsegmental PE, low recurrence risk → no anticoagulation\nNegative leg Doppler → does not rule out PE"},
{id:"pe4",g:"T",p:1,s:"p",t:"PE: which anticoagulant first, when do you thrombolyse, and what does heparin actually do?",k:"First: LMWH if stable with normal kidneys; otherwise UFH bolus + infusion\nThrombolysis only if high risk\nHeparin stops new clot → the body dissolves the old clot"},
{id:"pe-rv1",g:"C",p:1,s:"p",t:"Massive PE: why can intubation kill (the three hits)?",k:"Three hits at once:\nPositive-pressure breaths → cut blood returning to the RV\nInflated lungs → raise the load on the RV\nInduction drugs → lower the BP that feeds it\nThe failing RV spirals\n(Standard teaching, explained in The right heart, simply.)"},
{id:"pe-rv2",g:"T",p:1,s:"p",t:"Massive PE with hypoxia: why use high-flow nasal oxygen, and what is its limit?",k:"Patient keeps breathing on their own → no positive-pressure breaths, no sedation\nTreats low oxygen without the three hits\nOnly buys time → reperfusion is the fix"},
{id:"pe2",g:"T",p:1,s:"p",t:"Massive PE: how do you handle fluids, oxygen delivery and intubation (including the drugs)?",k:"Fluids: avoid big boluses (about 500 mL at most if hypotensive) → overstretch the RV\nIntubation: avoid if you can → positive-pressure breaths and sedatives cut blood returning to the RV, BP drops, failing RV can collapse\nInstead: high-flow nasal oxygen\nIf you must intubate: most experienced operator → ketamine → vasopressor (adrenaline or noradrenaline) ready first\n(Point of Care page; the drug choices are US teaching, not verified against an Australian source.)"},
{id:"pe3",g:"T",p:1,s:"p",t:"Crashing PE (shock or arrest): who do you call, and what are the treatment options?",k:"Call the PE response team\nAdrenaline (epinephrine)\nConsider pulmonary vasodilators (NO or epoprostenol), thrombolysis or thrombectomy, think ECMO\nPads and crash cart nearby\n(Point of Care page; the drug choices are US teaching, not verified against an Australian source.)\n(Victoria: Adult Retrieval Victoria coordinates transfer of critically ill adults and gives phone advice, 1300 36 86 61. Confirm who calls at GV Health.)"},
{id:"pe-h1",g:"T",p:2,s:"n",from:["h1794458820112"],t:"Crashing PE: what is the RV spiral, what can a vasopressor do and not do, and what do inhaled pulmonary vasodilators add?",k:"The spiral: clot raises RV load → RV fails → less blood to left heart → BP falls → low BP starves the RV of its own coronary flow → fails further\nVasopressor or inotrope (Australian ICU teaching: noradrenaline or adrenaline, or milrinone) → raises the BP that feeds the RV → buys time, does not shift the clot\nFix: reperfusion (thrombolysis, catheter treatment or surgery, via the PE response team)\nInhaled nitric oxide → relaxes only lung vessels → lowers RV load without dropping the BP → ICU decision, not an RMO one\nWhich pressor first: per your hospital protocol\n(Checked against LITFL, written by an Alfred ICU intensivist, and the Canberra Hospital PE response pathway; corrected from the pasted note, which put adrenaline first.)"},
{id:"pe5",g:"T",p:1,s:"p",t:"What are the absolute contraindications to tPA (strokes, surgery, trauma, bleeding)?",k:"Haemorrhagic stroke\nIschaemic stroke in the last 3 months\nAVM\nRecent brain or spine surgery\nHead trauma with fracture or brain injury in 3 weeks\nSerious active bleeding"},
{id:"pe7",g:"T",p:2,s:"p",t:"What are the relative contraindications to tPA?",k:"CNS tumour\nMajor surgery in 2-3 weeks\nPlatelets under 100, INR over 1.7, fibrinogen under 150\nOral anticoagulant\nBP over 180/110, age over 75\nAdvanced cirrhosis"},
{id:"pe15",g:"T",p:3,s:"p",t:"What did PEITHO show about thrombolysis in intermediate-risk PE, and when do you lyse?",k:"PEITHO, intermediate-risk PE: no long-term benefit → more major bleeding and haemorrhagic stroke\nLyse in massive PE → to prevent immediate death"},
{id:"pe8",g:"F",p:2,s:"p",t:"PE: what apixaban dosing, and how long do you treat provoked, unprovoked and cancer PE?",k:"Dose: apixaban 10 mg twice daily for 7 days → then 5 mg twice daily\nProvoked → 3 months\nUnprovoked with low bleeding risk → indefinite\nCancer → indefinite"},
{id:"pe13",g:"F",p:2,s:"p",t:"Unprovoked PE: what is the recurrence risk, and what follow-up tests (and not) do you do?",k:"Recurrence off treatment: about 10% in year 1 → then 5% a year\nDo: age-appropriate cancer screening\nDo not: thrombophilia testing in the acute phase (exception: high concern for antiphospholipid syndrome)"}
], sg: [
{id:"pes3",g:"R",p:3,s:"p",t:"Which DVTs carry the PE risk, and what is May-Thurner?",k:"Iliac, femoral and popliteal clots carry the PE risk; below the knee less so. May-Thurner: left iliac vein compressed by the right iliac artery."},
{id:"pes2",g:"A",p:2,s:"p",t:"PE imaging in pregnancy or kidney disease: what is first line, and what is the alternative?",k:"CT pulmonary angiogram is first line; V/Q scan is an alternative when contrast or radiation is a problem. (My suggestion from standard teaching.)"},
{id:"pes1",g:"T",p:1,s:"p",t:"Where must you check PE anticoagulant dosing in Australia?",k:"Not checked against Australian guidance. Look up the current eTG regimen before you rely on the apixaban dosing above. (My suggestion.)"}
]},

"atrial-fibrillation": { items: [
{id:"af-h4",g:"A",p:1,s:"p",from:["h1794311934960"],t:"New AF: which triggers do you look for, and which bloods do you send?",k:"Look for: thyroid, alcohol, sepsis, ischaemia, valve disease\nAlso: low K or Mg, PE, heart failure, recent surgery\nSend: TFTs, electrolytes with K and Mg, troponin, creatinine\nThe creatinine now also decides the anticoagulant dose"},
{id:"af2",g:"A",p:1,s:"p",t:"What are the CHA2DS2-VASc points?",k:"Heart failure 1\nHypertension 1\nAge 75+ 2\nDiabetes 1\nStroke or TIA 2\nVascular disease 1\nAge 65-74 1\nFemale 1"},
{id:"af1",g:"A",p:1,s:"p",t:"AF: who gets anticoagulated (CHA2DS2-VASc cut-offs)?",k:"CHA2DS2-VASc 2 or more in men\nCHA2DS2-VASc 3 or more in women\n(stroke risk 2% a year or more)"},
{id:"af13",g:"A",p:2,s:"p",from:["h1794308278402"],t:"AF: should a bleeding score stop anticoagulation, and which modifiable bleeding risks do you fix?",k:"Do not use a bleeding score (HAS-BLED) to withhold anticoagulation\nFix the modifiable risks: uncontrolled hypertension, alcohol, NSAIDs, antiplatelets, anaemia, labile INR"},
{id:"af4",g:"T",p:1,s:"p",t:"AF rate control: what heart-rate target (and with LV dysfunction), which first-line drugs, and which drug to avoid?",k:"Target: under 110 (under 80 if LV dysfunction or symptoms)\nFirst line: beta-blocker or diltiazem/verapamil\nAvoid: non-dihydropyridine CCB with moderate or severe LV systolic dysfunction"},
{id:"af5",g:"T",p:1,s:"p",t:"AF second-line rate control, and what do you do in pre-excited AF (WPW), stable vs unstable?",k:"Ordinary AF: digoxin (slow, about 2 hours) or amiodarone as backup\nPre-excited AF (WPW): no AV-nodal blockers, avoid IV amiodarone too\nUnstable → synchronised shock\nStable → procainamide (RACGP); availability in your hospital not confirmed, follow your protocol"},
{id:"af8",g:"T",p:2,s:"p",t:"AF: who benefits from rhythm control?",k:"Symptomatic despite rate control\nFirst episode\nHeart failure (especially HFrEF)\nYoung, athletes\nPatient preference"},
{id:"af-h5",g:"T",p:1,s:"b",from:["h1794310611494"],t:"Can this AF be cardioverted now: what do you do if unstable, stable under 48 hours, and stable over 48 hours?",k:"Unstable → shock now; do not wait for a TOE or anticoagulation\nStable, under 48 hours → cardioversion can proceed (with mild symptoms, rate control and watching is also fine)\nStable, over 48 hours or unknown → exclude left atrial thrombus with TOE first, or anticoagulate for weeks (ANZCOR 11.9)"},
{id:"af6",g:"T",p:1,s:"p",t:"Electrical cardioversion of AF: how do you do it, at how many joules, and what must you never do?",k:"Sedate → anteroposterior pads → synchronise to the QRS → start about 100 J biphasic\nNever defibrillate AF"},
{id:"af9",g:"T",p:2,s:"p",t:"Drug cardioversion of AF: when flecainide or propafenone, and what otherwise?",k:"Flecainide or propafenone → only without structural heart disease or coronary disease\nOtherwise: amiodarone, dofetilide or ibutilide"},
{id:"af3",g:"F",p:1,s:"p",from:["h1794308329681"],t:"AF: which anticoagulant first line, and in which valve and kidney situations warfarin?",k:"First line: DOAC for non-valvular AF\nWarfarin (INR 2-3) → moderate to severe mitral stenosis, mechanical valves, or CrCl under 15 if apixaban not possible\nAspirin alone is not enough"},
{id:"af-h2",g:"F",p:1,s:"a",from:["h1794308325768"],t:"AF with cirrhosis: can you use a DOAC (Australian apixaban product information)?",k:"DOACs are contraindicated in cirrhosis\nAustralian apixaban product information: contraindicated in liver disease with coagulopathy and clinically relevant bleeding risk, including severe (Child-Pugh C); caution in mild or moderate\nCheck the product information for rivaroxaban and dabigatran"},
{id:"af7",g:"F",p:2,s:"p",t:"What are the DOAC doses and dose reductions in AF?",k:"Apixaban 5 mg twice daily → 2.5 mg if two of: 80+, 60 kg or less, creatinine 1.5+\nRivaroxaban 20 mg with food → 15 mg if CrCl 15-50\nEdoxaban 60 → 30\nDabigatran 150 twice daily → 110\nCheck Australian product information"},
{id:"af14",g:"F",p:3,s:"b",t:"AF after PCI: what antithrombotics, for how long, and what at 12 months?",k:"Why: stent needs antiplatelets, AF needs an anticoagulant, all three raise bleeding a lot\nSo: stop aspirin early (US page 1-4 weeks; Australian review about 1 month)\nKeep: anticoagulant + P2Y12 inhibitor\nClopidogrel preferred over ticagrelor or prasugrel; DOAC preferred over warfarin\nAt 12 months → stop the antiplatelet, keep the anticoagulant alone\n(NHFA/CSANZ 2018 via Medicine Today 2019; check eTG)"},
{id:"af10",g:"F",p:2,s:"p",t:"Which drugs keep sinus rhythm in AF, and what are the cautions?",k:"Class Ic → avoid in CAD or structural disease\nAmiodarone, sotalol, dofetilide, dronedarone\nAdvanced conduction disease → no antiarrhythmic without pacing"},
{id:"af11",g:"F",p:2,s:"p",t:"AF catheter ablation: what is done, who does best, and what about anticoagulation after?",k:"Pulmonary vein isolation\nWorks best: paroxysmal AF (70-80%), heart failure, young symptomatic patients\nAnticoagulation after → based on the score, not the rhythm"},
{id:"af12",g:"F",p:2,s:"p",t:"AF: which risk factors do you modify, and with what targets?",k:"Weight loss 10% or more\nExercise 210 minutes a week\nBP under 130/80\nTreat sleep apnoea\nAlcohol under 3 drinks a week\nStop smoking, glycaemic control\nCaffeine restriction not advised"},
{id:"af-h1",g:"C",p:1,s:"p",from:["h1794308709478"],t:"Why give an AV-nodal blocker before flecainide, and when must you not?",k:"Flecainide slows the atria (flutter about 300 → 220)\nAV node can now pass every beat 1 to 1 → ventricles race at about 220\nSo: give the AV-nodal blocker first\nOnly in ordinary AF or flutter → in pre-excited AF give none"},
{id:"af-h3",g:"C",p:1,s:"p",from:["h1794310065418"],t:"Pre-excited AF: why are AV-nodal blockers dangerous, which drugs do you avoid, and what if unstable?",k:"AV node has a speed limiter; the accessory pathway (delta wave) does not\nBlocking the node → fast atrial rate goes down the accessory pathway → ventricles can go dangerously fast\nAvoid: beta-blockers, verapamil, diltiazem, digoxin\nUnstable → synchronised shock"},
{id:"af15",g:"F",p:3,s:"p",t:"AF burden: how long an episode carries stroke risk, and when is risk highest?",k:"Episodes over 17-24 hours → significant risk\nOver twofold risk from 1 hour\nRisk highest in the 5 days after an episode"}
], sg: [
{id:"afs1",g:"T",p:1,s:"a",t:"Unstable AF: which signs, and what is the treatment?",k:"Adverse signs (low BP, chest pain, heart failure, confusion, very fast rate) mean cardioversion with sedation, not drugs first (ANZCOR 11.9)."},
{id:"afs4",g:"R",p:2,s:"p",t:"Why does the QRS width change beat to beat in pre-excited AF?",k:"Some beats go down the AV node (narrower QRS) and some down the accessory pathway (wider QRS), so the width changes beat to beat and the rhythm is irregular. (My suggestion.)"},
{id:"afs3",g:"T",p:2,s:"b",t:"Where do you find the Australian version of the AF rate-control order?",k:"Open the AF Study Kit (Australia first) in this app: it compares the US page with Australian guidance."}
]},

"bradycardia": { items: [
{id:"br13",g:"R",p:3,s:"p",t:"Bradycardia: what rate defines it, when do symptoms start, and what are sick sinus, junctional and physiological bradycardia?",k:"Bradycardia: under 60, but symptoms usually start under 50\nSick sinus syndrome: SA node dysfunction\nJunctional rhythm: starts in the AV node\nAthletes and sleep: can be physiological"},
{id:"br7",g:"R",p:1,s:"p",t:"What are the four heart blocks, and how does the PR behave in each?",k:"First degree: long fixed PR\nMobitz I: PR lengthens → then a drop\nMobitz II: fixed PR → sudden drops\nComplete: atria and ventricles independent"},
{id:"br-h1",g:"R",p:2,s:"p",from:["h1794313233298"],t:"Complete heart block: what sets the beat, and how do junctional and ventricular escape differ?",k:"Nothing gets through → a backup pacemaker below the block sets the beat\nHigher backup = better\nBlock at the AV node → junctional escape: 40-60 a minute, narrow QRS, steadier\nBlock in the wires below → ventricular escape: 20-40 a minute, wide QRS, unreliable (LITFL)"},
{id:"br1",g:"R",p:1,s:"a",t:"Bradycardia: which adverse signs make the patient unstable?",k:"Systolic BP under 90\nHeart rate under 40\nVentricular arrhythmia\nHeart failure\n(US page also lists: confusion, chest pain, breathlessness)"},
{id:"br8",g:"R",p:1,s:"a",t:"Which bradycardia findings mark asystole risk, and what do you do even if the patient looks well?",k:"Marks asystole risk:\nRecent asystole, Mobitz II\nComplete block with broad QRS or rate under 40\nPause over 3 seconds\n→ pads on + call cardiology, even if the patient looks well"},
{id:"br11",g:"A",p:2,s:"p",t:"Bradycardia: what is the first-hour work-up?",k:"Telemetry, 12-lead ECG\nFBC, UEC (with potassium), TSH, troponin\nEcho\nCheck: prior ECGs, drug chart, prior heart disease"},
{id:"br4",g:"A",p:1,s:"p",t:"Bradycardia: what are the four can't-miss causes?",k:"ACS (especially inferior MI)\nComplete heart block\nBeta-blocker or calcium-channel blocker toxicity\nHyperkalaemia"},
{id:"br10",g:"A",p:2,s:"p",t:"Bradycardia: which reversible causes do you look for?",k:"Drugs: beta-blockers, CCBs, amiodarone, opioids, SSRIs\nHyperkalaemia, hypothyroidism, hypothermia\nRaised intracranial pressure\nInfection (Lyme, endocarditis)\nIschaemia, vagal tone"},
{id:"br6",g:"C",p:1,s:"p",t:"When will atropine not work?",k:"Atropine fails in:\nComplete heart block (especially wide QRS)\nBlock below the AV node\nTransplanted heart\nThe page also warns about acute MI"},
{id:"br9",g:"C",p:2,s:"p",t:"Block at the AV node vs below it: why does each behave differently, and what does atropine do?",k:"Block at the AV node: node tires gradually → slow cells need time to reset → each early signal passes more slowly → warning signs; atropine helps\nBlock below (the wires): fast and all-or-none → conduct or fail suddenly → no warning; atropine fails and can make it worse\nSee the Heart block pages in this app"},
{id:"br2",g:"T",p:1,s:"b",t:"Atropine for bradycardia: what dose in Australia, how often, up to what maximum, and why not too low?",k:"Australia: 500-600 mcg IV every 3-5 minutes → up to 3 mg\nUS page: 1 mg a dose\nToo low a dose can slow the heart further"},
{id:"br3",g:"T",p:1,s:"a",t:"If atropine fails: what adrenaline infusion, how do you pace, and how do you confirm capture?",k:"Adrenaline infusion: 2-10 mcg/min\nOr pacing: transcutaneous at 70-80 a minute, start near 30 mA → until capture\nCapture = QRS after every spike + a pulse\nChest twitching proves nothing"},
{id:"br5",g:"T",p:1,s:"b",t:"Beta-blocker or calcium-channel blocker toxicity: what do you give, and who do you call?",k:"Glucagon\nOr insulin with glucose and potassium\nMuch higher adrenaline doses\nCall: Poisons Information Centre 13 11 26\nThe glucagon dose is not in the Australian source → use toxicology guidance"},
{id:"br12",g:"F",p:2,s:"p",t:"What are the indications for a permanent pacemaker?",k:"Symptomatic sinus bradycardia (with or without pauses)\nComplete heart block\nSymptomatic second-degree block\nSyncope from bradycardia\nCorrect reversible causes first → involve EP"}
], sg: [
{id:"brs1",g:"A",p:2,s:"p",t:"Hyperkalaemia: what does the ECG show, and how is it treated?",k:"Peaked T, wide QRS, loss of P waves; IV calcium, insulin with glucose, per your protocol. (My suggestion from standard teaching.)"},
{id:"brs2",g:"C",p:2,s:"p",t:"Inferior MI with bradycardia: how do you treat it?",k:"Treat both together: ACS pathway, atropine reasonable, pace early, avoid nitrates when hypotensive. (My suggestion.)"},
{id:"brs4",g:"R",p:1,s:"p",t:"Mobitz I: why does the AV node tire and the PR lengthen until a beat drops?",k:"The node's slow cells need time to reset after each beat. If the next signal arrives before the reset is done, it passes slowly, so PR lengthens until one beat is blocked; the pause lets the node reset. Nothing is damaged. The sinus node sets the rate; the AV node only passes signals on. (My suggestion from standard teaching.)"},
{id:"brs5",g:"R",p:2,s:"p",t:"When does Mobitz I appear, and is it harmful?",k:"A healthy node keeps up at normal rates. Mobitz I appears when the node needs longer to reset (drugs, scarring, inferior MI, strong vagal tone: athletes, sleep) or is pushed past its limit by a very fast atrial rate. Usually benign. (My suggestion.)"},
{id:"brs6",g:"R",p:1,s:"p",t:"Mobitz II: why is there no warning, what can it progress to, and why can atropine make it worse?",k:"The wires below the node are fast and all-or-none: PR stays fixed and a beat drops suddenly. The disease often spreads, so it can progress to complete block with a slow, wide escape rhythm. Atropine speeds the node and can send more signals at a diseased wire. (My suggestion.)"},
{id:"brs7",g:"R",p:2,s:"p",t:"Why is bundle branch block not heart block, and why is the QRS wide?",k:"In BBB one branch is blocked and the other carries every signal: PR is normal and no beats drop. The QRS is wide because the blocked side is activated slowly through muscle. A wide QRS tells you the route was slow, not the cause. (My suggestion.)"},
{id:"brs8",g:"C",p:3,s:"p",t:"What is rate-related bundle branch block, and what causes it?",k:"A branch can block only at faster rates because it has not recovered in time, so the QRS goes wide as the rate rises. The cause is the fast atrial rate, not the AV node over-firing. (My suggestion.)"},
{id:"brs3",g:"T",p:3,s:"p",t:"Sedation for pacing: what does the US page suggest, and what does ANZCOR say?",k:"The US page suggests fentanyl then midazolam; ANZCOR names none. Use your hospital protocol and senior help."}
]},

"tachyarrhythmias-rapid-response": { items: [
{id:"tc1",g:"R",p:1,s:"a",t:"Tachycardia: which adverse signs mean unstable, and what is the treatment?",k:"Adverse signs: systolic BP under 90, heart rate over 150, chest pain, heart failure, drowsy or confused\nUnstable → synchronised cardioversion with sedation"},
{id:"tc3",g:"R",p:1,s:"p",t:"Tachycardia: what goes in each of the four boxes (narrow or wide, regular or irregular)?",k:"Narrow regular → sinus, flutter, AVNRT/AVRT\nNarrow irregular → AF, MAT\nWide regular → VT\nWide irregular → AF with block, pre-excited AF, torsades"},
{id:"tc10",g:"R",p:2,s:"p",from:["h1794384906613"],t:"What are the causes of sinus tachycardia, and how do you treat it?",k:"A sign, not a rhythm to treat\nCauses: pain, anxiety, bleeding or hypovolaemia, fever or sepsis, hypoxia, PE, heart failure, ACS, alcohol withdrawal, thyroid, caffeine, drugs\nFind and treat the cause\nNever shock it or slow it with drugs"},
{id:"tc11",g:"A",p:2,s:"p",t:"Tachycardia: what do you do in the first minute at the bedside?",k:"Oxygen if low → monitor → IV → pads → 12-lead ECG\nBloods: K, Mg, troponin, lactate, TSH\nCall your senior\nNo pulse → arrest algorithm"},
{id:"tc7",g:"C",p:1,s:"a",t:"Pre-excited AF: which drugs do you avoid, what is safest, and what if you can't tell it from VT?",k:"Avoid: adenosine, digoxin, verapamil, diltiazem\nSafest: electrical cardioversion (usually)\nCannot tell it from VT → treat the same way: pads on, 12-lead ECG, call your senior early\nUnstable → synchronised shock"},
{id:"tc4",g:"T",p:1,s:"a",t:"Narrow regular tachycardia, stable: what is the treatment sequence and doses?",k:"Valsalva\n→ adenosine 6 mg\n→ adenosine 12 mg (flush at least 20 mL)\n→ verapamil 2.5-5 mg or diltiazem 15-20 mg if adenosine is unsuitable"},
{id:"tc8",g:"T",p:2,s:"a",t:"How do you do the modified Valsalva, and how well does it work?",k:"Strain into a 10 mL syringe for 15 seconds\n→ lie flat, legs raised 45 degrees, for 15 seconds\nConverts about 43% (standard Valsalva 5-20%)"},
{id:"tc9",g:"T",p:2,s:"a",t:"Narrow irregular (AF), stable: which drugs and doses, and when can you not cardiovert?",k:"Metoprolol 5 mg IV (not with wheeze or decompensated heart failure)\nOr digoxin 250-500 mcg\nOver 48 hours → no cardioversion unless anticoagulated or TOE clear"},
{id:"tc5",g:"T",p:1,s:"a",t:"Wide regular tachycardia: what do you treat it as, which drug and dose, and what must you never give?",k:"Treat it as VT\nAmiodarone 300 mg over 20-60 minutes → then 900 mg over 24 hours\nNever verapamil or diltiazem"},
{id:"tc6",g:"T",p:1,s:"a",t:"Torsades: what do you stop, correct and give (magnesium dose), what do you avoid, and what if unstable?",k:"Stop QT drugs\nCorrect potassium\nMagnesium 5 mmol IV over 10 minutes (may repeat once) → then 20 mmol over 4 hours\nAvoid amiodarone\nAdverse signs (shock) → unstable\nThe US page's '2-4 mg' looks like a typo for grams"},
{id:"tc2",g:"T",p:1,s:"a",t:"Tachycardia: if the shock fails, what do you give and then do?",k:"Amiodarone 300 mg IV over 10-20 minutes\n→ repeat the shock\n→ then 900 mg over 24 hours"},
{id:"tc12",g:"T",p:3,s:"p",t:"Sedation for cardioversion: what does the US page suggest, and what does ANZCOR say?",k:"US page: fentanyl 50 mcg + midazolam 1-2 mg\nANZCOR: names no drug or dose\n→ use your protocol and senior or anaesthetic help"},
{id:"tc13",g:"T",p:3,s:"p",t:"What is the respiratory support ladder, and when BiPAP vs CPAP?",k:"Non-rebreather → HFNC → NIPPV → intubate\nNIPPV: BiPAP for COPD, CPAP for heart failure\nWatch PaCO2 and pH"}
], sg: [
{id:"tcs1",g:"T",p:1,s:"p",t:"Adenosine: what side effects do you warn about, and when do you avoid it?",k:"Brief chest tightness and a pause are expected; warn the patient. Avoid in pre-excited AF. (My suggestion from standard teaching.)"},
{id:"tcs3",g:"T",p:3,s:"a",t:"VT during acute MI: when is lignocaine reasonable (ANZCOR)?",k:"ANZCOR calls it reasonable for stable sustained monomorphic VT with ischaemia, and gives no dose."},
{id:"tcs4",g:"R",p:1,s:"p",t:"What does a wide QRS mean, and what are the three reasons for it?",k:"The signal took a slow route through muscle. Three reasons: the beat starts in the ventricle (VT), a fast wire is blocked (bundle branch block or aberrancy), or the signal came down an accessory pathway (pre-excitation). Wide tells you the route was slow, not the cause. (My suggestion.)"},
{id:"tcs5",g:"R",p:1,s:"p",t:"Wide tachycardia: what does regular vs irregular suggest?",k:"Wide, regular, same shape every beat: think VT (one focus firing like a metronome). Wide, irregular, shape changing beat to beat: think AF down an accessory pathway or AF with block. (My suggestion.)"},
{id:"tcs6",g:"A",p:1,s:"p",t:"What are the clues for pre-excited AF?",k:"Young patient, past episodes of fast palpitations, old ECG with a delta wave, irregular rate over 200 with a QRS width that changes beat to beat. Find his old ECGs. (My suggestion.)"},
{id:"tcs2",g:"F",p:2,s:"p",t:"After a tachycardia converts: what do you do?",k:"Repeat the 12-lead (delta wave?), check K and Mg, find the cause, tell your senior or cardiology. (My suggestion.)"}
]},
"respiratory-distress-rapid-response": { items: [
{id:"rd1",g:"R",p:1,s:"g",t:"Respiratory distress: what do you look at first, and what do you do straight away?",k:"Look: talking? rate, effort, SpO2, pulse, BP, drowsiness\nDo: sit up → monitor → IV access → call for help early"},
{id:"rd2",g:"R",p:1,s:"g",t:"What are the oxygen targets for most adults and for CO2 retainers, and when is oxygen not needed?",k:"Most acutely unwell adults: 92 to 96%\nCOPD or CO2 retainers: 88 to 92% (TSANZ)\nNo oxygen for breathlessness without hypoxia"},
{id:"rd3",g:"R",p:2,s:"g",t:"Stridor or facial swelling: what do you give, and who do you call?",k:"Upper airway obstruction or anaphylaxis\n→ IM adrenaline + call anaesthetics early"},
{id:"rd4",g:"R",p:1,s:"g",t:"How do you diagnose tension pneumothorax, and do you wait for imaging?",k:"Breathless + absent air entry one side + low BP + high airway pressures\n→ decompress without waiting for imaging"},
{id:"rd5",g:"A",p:1,s:"g",t:"How do you read a gas: type 1 vs type 2 failure, and acute vs chronic?",k:"Type 1: low O2, normal or low CO2\nType 2: high CO2\nHigh CO2 + low pH → acute\nHigh bicarbonate → chronic"},
{id:"rd6",g:"A",p:2,s:"g",t:"Venous vs arterial gas: what can a venous gas tell you, and what can't it?",k:"Venous gas gives: pH, approximate CO2\nCannot assess: oxygenation (MJA 2015)"},
{id:"rd7",g:"A",p:2,s:"g",t:"Respiratory distress: which bedside tests in the first minutes?",k:"12-lead ECG\nGlucose\nBloods\nChest X-ray or bedside ultrasound"},
{id:"rd8",g:"T",p:1,s:"g",t:"Respiratory distress: what is the first move for wheeze, oedema, anaphylaxis and opioid excess?",k:"Wheeze → bronchodilator\nOedema → sit up + CPAP\nAnaphylaxis → IM adrenaline\nOpioid excess → support breathing + titrated naloxone per protocol"},
{id:"rd9",g:"T",p:1,s:"g",t:"What is the oxygen ladder, and how do you climb it?",k:"Cannula, Venturi or simple mask → non-rebreather → high-flow → CPAP or BiPAP → intubation\nMove up one rung at a time"},
{id:"rd10",g:"T",p:1,s:"g",dup:"rd16",t:"Which failure does CPAP treat, and which does BiPAP treat?",k:"CPAP → pulmonary oedema (low oxygen)\nBiPAP → hypercapnic acidosis (high CO2 with a low pH)\nMatch the support to the type of failure"},
{id:"rd15",g:"T",p:1,s:"p",t:"Why use a Venturi mask for CO2 retainers?",k:"Think of cordial mixed at the tap: fixed ratio → every glass the same strength\nVenturi valve: jet of pure oxygen drags room air in through side holes → hole size sets the ratio (blue 24%, white 28%)\nFlow is far more than the patient breathes in → breathing harder cannot change the mix\nResult: fixed percentage → can hit 88 to 92% without overshooting\nSimple mask or non-rebreather: varies or gives too much\nWhy it matters: too much oxygen in a CO2 retainer → CO2 rises → drowsy\n(Standard teaching; flow per the valve or device label, not checked against a specific Australian product.)"},
{id:"rd16",g:"T",p:1,s:"p",t:"CPAP vs BiPAP: what does each pressure do, and which problem does each fix?",k:"CPAP: one steady pressure keeps air spaces open → low oxygen from pulmonary oedema or pneumonia\nBiPAP: adds a push on each breath in → high CO2 with a low pH\n(Standard teaching.)"},
{id:"rd17",g:"T",p:2,s:"p",t:"Why do low-flow devices give a varying oxygen percentage, and how is high-flow different?",k:"Low-flow (cannula, simple mask): breathless patient breathes in faster than the device delivers → fills the gap from room air → real percentage varies with each breath\nHigh-flow nasal oxygen: meets their flow → the setting is what they get\nVenturi is the other fix: very high total flow from a fixed mix → same idea"},
{id:"rd11",g:"C",p:1,s:"g",t:"Why must you not sedate a breathless, agitated patient?",k:"Anxiety and agitation are often hypoxia or high CO2\n→ do not sedate"},
{id:"rd12",g:"C",p:2,s:"g",t:"Sudden low saturation, clear chest, recent surgery: what do you think of first?",k:"Sudden low saturation + clear chest + recent surgery\n→ think pulmonary embolism before pneumonia"},
{id:"rd13",g:"F",p:1,s:"g",t:"Respiratory distress: when do you call ICU outreach, and what do you check early?",k:"Call ICU outreach if: drowsy, silent chest, rising CO2 or falling pH, hypotension, oxygen need rising\nCheck treatment limits early\n(Victoria: Adult Retrieval Victoria coordinates transfer of critically ill adults and gives phone advice, 1300 36 86 61. Confirm who calls at GV Health.)"},
{id:"rd14",g:"F",p:2,s:"g",t:"How do you hand over a breathless patient in 20 seconds?",k:"Who → what you see → what you think → what you have done → what you need\nInclude the gas"}
], sg: [
{id:"rds1",g:"A",p:2,s:"g",t:"Deep, fast breathing with a clear chest: what do you look for, and what causes it?",k:"Kussmaul breathing with a clear chest: look for metabolic acidosis (DKA, sepsis, toxins)."}
]},
"asthma-exacerbation": { items: [
{id:"as1",g:"R",p:1,s:"g",t:"Asthma: how do you grade severity as mild to moderate, severe or life-threatening?",k:"Grade by the worst feature\nMild to moderate: full sentences, SpO2 over 94%\nSevere: cannot finish a sentence, accessory muscles, SpO2 94% or below\nLife-threatening: drowsy, exhausted, cyanosed, poor effort, or SpO2 under 92%"},
{id:"as2",g:"R",p:1,s:"g",t:"Asthma with a silent chest, drowsy or exhausted: what does it mean, and who do you call?",k:"Life-threatening: little air is moving\n→ call ICU and your senior"},
{id:"as3",g:"A",p:2,s:"g",t:"Asthma: which causes or complications do you look for?",k:"Pneumothorax → suddenly worse or unequal air entry\nAnaphylaxis\nPneumonia\nBeta-blocker or NSAID"},
{id:"as4",g:"A",p:2,s:"g",t:"Asthma: is a chest X-ray routine, and when do you do one?",k:"Not routine\nOnly if you suspect pneumothorax or pneumonia"},
{id:"as5",g:"T",p:1,s:"g",t:"Mild to moderate asthma: what salbutamol dose, by what device, and how often?",k:"Salbutamol 4 to 12 puffs (100 micrograms each) by pMDI + spacer\nRepeat every 20 minutes in the first hour if needed\nThen every 4 to 6 hours"},
{id:"as6",g:"T",p:1,s:"g",t:"Severe asthma: what salbutamol and ipratropium doses, and how often?",k:"Salbutamol 12 puffs by spacer every 20 minutes in the first hour (or a 5 mg nebule if no spacer)\nPlus ipratropium 8 puffs (21 micrograms each) every 20 minutes\nThen 4 to 6 hourly"},
{id:"as7",g:"T",p:1,s:"g",t:"Life-threatening asthma: what bronchodilators, how given, and where does the patient go?",k:"Continuous nebulisation: 2 x 5 mg salbutamol nebules, oxygen-driven\nPlus ipratropium 500 micrograms every 20 minutes for the first hour\nImmediate transfer to higher-level care"},
{id:"as8",g:"T",p:1,s:"g",t:"Asthma: when do you start oxygen, and what is the target?",k:"Start if SpO2 under 92%\nTarget 92 to 96%\n88 to 92% if CO2 retention is a risk"},
{id:"as9",g:"T",p:1,s:"g",t:"Asthma: what oral steroid, what dose, when, and for how long?",k:"Oral prednisolone early\nAustralian Prescriber: 50 mg first dose → then 25 mg twice daily, about 7 to 10 days\nConfirm in your hospital protocol"},
{id:"as10",g:"C",p:1,s:"g",t:"Breathless asthmatic: what does a normal or rising CO2 mean?",k:"They are tiring\nEarly in an attack: fast breathing blows off CO2 → CO2 should be low\nNormal CO2 → can no longer keep that up\nRising CO2 → ventilation is failing"},
{id:"as11",g:"C",p:1,s:"g",t:"Asthma: when is IV magnesium used, and who decides?",k:"A senior decision\nIV magnesium for severe attacks not responding\nDose per your hospital protocol (not verified here)"},
{id:"as12",g:"C",p:1,s:"g",t:"Asthma: can you sedate a tiring patient?",k:"Never\nBenzodiazepines and opioids can precipitate respiratory arrest in a tiring asthmatic"},
{id:"as13",g:"C",p:1,s:"g",t:"Asthma suddenly worse with one side silent: what do you think of, and what do you do?",k:"Think: tension pneumothorax\nSigns: absent air entry one side, hypotension, neck veins\nDecompress → do not send for an X-ray first"},
{id:"as14",g:"F",p:1,s:"g",t:"Asthma discharge: what must be in place?",k:"Never discharge on a reliever alone\nPreventer with an inhaled steroid\nWritten action plan\nSpacer technique\nGP review within a few days"},
{id:"as15",g:"F",p:2,s:"g",t:"Acute asthma: when do you reassess, and when do you escalate?",k:"Reassess at 20 minutes, one hour, and after each change\nNot improving at one hour → escalate"}
], sg: [
{id:"ass1",g:"T",p:3,s:"g",t:"Asthma in children: which guideline for dosing?",k:"Use the RCH guideline for paediatric dosing, not the adult page."}
]},
"copd-exacerbation": { items: [
{id:"co1",g:"R",p:1,s:"g",t:"What defines a COPD flare, which conditions mimic it, and which drug causes do you check for?",k:"Flare: more breathless, more sputum, purulent sputum\nInfection is common, but rule out mimics: heart failure, pneumonia, pneumothorax, PE, new arrhythmia such as AF (chest X-ray and ECG pick most up, NSW ACI)\nDrug causes: missed inhalers, newly started beta-blocker, sedative (opioid or benzodiazepine) that slows breathing (drug list not in the NSW ACI page; check your hospital protocol)\nNot responding → think of the mimics again",from:["h1794638971179"]},
{id:"co2",g:"R",p:1,s:"g",t:"COPD flare: what do you ask about early?",k:"Treatment limits\nIs ICU or intubation appropriate for this patient?"},
{id:"co3",g:"A",p:1,s:"g",t:"COPD flare: when do you do an arterial gas, and what do you look at?",k:"When: drowsy, severe, or low saturation\nLook at: pH and CO2 before and after oxygen changes"},
{id:"co4",g:"A",p:2,s:"g",t:"COPD flare: which tests?",k:"Chest X-ray, ECG, bloods\nSputum culture if purulent\nTroponin and BNP if unclear"},
{id:"co5",g:"T",p:1,s:"g",t:"COPD flare: what oxygen target, by which devices, and why avoid excess?",k:"Target: 88 to 92%\nDevices: nasal prongs 0.5 to 2 L/min, or Venturi 24% or 28%\nExcess oxygen can worsen hypercapnia"},
{id:"co6",g:"T",p:1,s:"g",t:"COPD flare: what bronchodilator doses, by spacer and by nebuliser?",k:"Salbutamol: spacer 400 to 800 micrograms, or nebulised 2.5 to 5 mg\nIpratropium: spacer 80 micrograms, or nebulised 500 micrograms\nTitrate hourly to six-hourly"},
{id:"co7",g:"T",p:1,s:"g",t:"COPD flare: what prednisolone dose, and for how long?",k:"Prednisolone 40 to 50 mg daily\nNSW ACI: up to two weeks is adequate; shorter courses are common\nFollow your protocol"},
{id:"co8",g:"T",p:2,s:"g",t:"COPD flare: when do you give an antibiotic, and which?",k:"If the sputum is purulent\nCover typical and atypical organisms\nAgent and dose per eTG and your hospital protocol"},
{id:"co9",g:"T",p:1,s:"g",t:"COPD flare: when do you consider NIV?",k:"Respiratory acidosis (NSW ACI: pH under 7.3 or worsening; many protocols start under 7.35 with a raised CO2)\nDrowsiness\nSevere breathlessness\nPersistent hypoxaemia"},
{id:"co10",g:"C",p:1,s:"g",t:"COPD patient drowsy on high oxygen with a slow rate: what is happening, and what do you do?",k:"Over-oxygenation\n→ reduce to the target + check a gas"},
{id:"co11",g:"C",p:1,s:"g",t:"COPD on NIV: what do you recheck and when, what should happen, and what if it does not?",k:"Recheck: gas, breathing rate and effort, usually within an hour (timing per your unit's NIV protocol)\nThey should improve\nNot improving or worse → call ICU → discuss intubation within the agreed treatment limits\n(Victoria: Adult Retrieval Victoria coordinates transfer of critically ill adults and gives phone advice, 1300 36 86 61. Confirm who calls at GV Health.)",from:["h1794639154135"]},
{id:"co12",g:"C",p:2,s:"g",dup:"co1",t:"Wheeze not responding to COPD treatment: what else could it be?",k:"Not always COPD\nThink: heart failure, pneumothorax, PE, arrhythmia"},
{id:"co13",g:"F",p:1,s:"g",t:"COPD flare: what are the admission criteria?",k:"Marked symptoms + failure at home\nLoss of mobility, cannot eat or sleep\nAltered mental state\nWorsening hypoxaemia\nRight heart failure or new arrhythmia"},
{id:"co14",g:"F",p:2,s:"g",t:"COPD: what must happen before discharge?",k:"Inhaler technique\nPreventer plan\nSmoking cessation\nVaccines\nPulmonary rehabilitation\nWritten action plan + early review"}
], sg: [
{id:"cos1",g:"C",p:2,s:"g",t:"COPD CO2 retainer: what drives the nebuliser, and how do you give oxygen?",k:"Nebulise with air, and give controlled oxygen by nasal prongs alongside (standard teaching)."}
]},
"community-acquired-pneumonia": { items: [
{id:"pn1",g:"R",p:1,s:"g",t:"How does pneumonia present, and what are its mimics?",k:"Presents: fever, cough, focal signs, new shadow on X-ray\nMimics: heart failure, PE, aspiration, lung cancer, TB"},
{id:"pn2",g:"R",p:1,s:"g",t:"Pneumonia: which red flags mean hospital?",k:"RR over 22, HR over 100\nConfusion\nSBP under 90, SpO2 under 92%\nMultilobar X-ray\nVomiting, no social support, unstable comorbidities"},
{id:"pn3",g:"A",p:1,s:"g",t:"Pneumonia: how do CURB-65 and CORB guide where to treat?",k:"CURB-65: above 1 → inpatient; above 2 → consider HDU or ICU\nCORB: confusion, SaO2 90% or below, RR 30 or more, low BP"},
{id:"pn4",g:"A",p:1,s:"g",t:"Pneumonia: which tests before antibiotics?",k:"Chest X-ray, bloods\nBlood cultures (if no delay)\nSputum culture\nAdmitted and sick → urine antigens + viral PCR"},
{id:"pn5",g:"T",p:1,s:"g",t:"Mild CAP: which antibiotic, what dose, alternatives, and how long (TG v16)?",k:"Amoxicillin 1 g orally 8-hourly\nAtypical suspected or penicillin allergy → doxycycline 100 mg 12-hourly or clarithromycin 500 mg 12-hourly\nDuration: 5 to 7 days (TG v16)"},
{id:"pn6",g:"T",p:1,s:"g",t:"Moderate CAP: where is it treated, which antibiotics, and when do you step down?",k:"Admit\nIV benzylpenicillin 1.2 g 6-hourly + doxycycline\nImproving → step down to oral amoxicillin\n(2011 summary; check eTG)"},
{id:"pn7",g:"T",p:1,s:"g",t:"Severe CAP: which antibiotics, where, and when do you call ID?",k:"Ceftriaxone 1 g IV daily + azithromycin 500 mg IV daily\nHDU or ICU\nID if: allergic, returned traveller, Staph aureus risk\n(2011 summary; check eTG)"},
{id:"pn8",g:"T",p:2,s:"g",t:"Pneumonia: when do you give oxygen?",k:"Give if SpO2 under 92% → to the target range"},
{id:"pn9",g:"C",p:1,s:"g",t:"Pneumonia with sepsis: what are the signs, and what do you do?",k:"Signs: shock, high lactate, organ dysfunction\n→ sepsis pathway + antibiotics without delay"},
{id:"pn10",g:"C",p:1,s:"g",t:"Pneumonia not responding at 48 hours: what do you do?",k:"Reassess\nRepeat the X-ray and cultures\nMild CAP → add doxycycline or clarithromycin"},
{id:"pn11",g:"C",p:1,s:"g",t:"Pneumonia not improving at 5 days: what do you look for, and with what?",k:"Look for empyema or lung abscess\n→ ultrasound or CT"},
{id:"pn12",g:"F",p:2,s:"g",t:"Pneumonia: when do you step down to oral antibiotics?",k:"When clinically improving\nComplete the course"},
{id:"pn13",g:"F",p:2,s:"g",t:"After pneumonia: when do you repeat the chest X-ray, and for whom?",k:"About 6 weeks, if the first film was abnormal\n(TG via Medicine Today)"},
{id:"pn14",g:"F",p:3,s:"g",t:"Pneumonia: what do you offer before discharge?",k:"Vaccines\nSmoking cessation"}
], sg: [
{id:"pns1",g:"A",p:2,s:"g",t:"CAP with penicillin allergy: what do you do for immediate vs non-immediate reactions?",k:"Immediate reaction: discuss with ID. Non-immediate: ceftriaxone may be possible (2011 summary)."}
]},
"pneumothorax": { items: [
{id:"px1",g:"R",p:1,s:"g",t:"How do you diagnose tension pneumothorax, and do you wait for imaging?",k:"Clinical: shock, severe breathlessness, absent air entry one side, high airway pressures if ventilated\nDo not wait for imaging"},
{id:"px2",g:"R",p:2,s:"g",t:"What are the types of pneumothorax?",k:"Primary: young, tall, thin\nSecondary: lung disease\nTraumatic\nIatrogenic\nTension"},
{id:"px3",g:"A",p:1,s:"g",t:"How do you confirm a pneumothorax?",k:"Upright chest X-ray\nBedside ultrasound → no lung sliding, lung point\nCT if unclear and stable"},
{id:"px4",g:"T",p:1,s:"g",t:"Tension pneumothorax: how do you decompress (needle, site), and what if no improvement?",k:"Decompress → then drain\n14 or 16 gauge cannula\nAdult site per your protocol (Australian paediatric guideline: second intercostal space, mid-clavicular line, 90 degrees)\nNo improvement → second attempt about 1 cm away"},
{id:"px5",g:"T",p:1,s:"g",t:"Small primary pneumothorax with little breathlessness: what do you do?",k:"Observe\nDischarge with early review if they can come back easily (NSW ACI)"},
{id:"px6",g:"T",p:1,s:"g",t:"Large or symptomatic primary pneumothorax, stable: what do you do, and how?",k:"Aspirate with 14 to 16 gauge\nStop at: resistance, excessive cough, or 2.5 L\nRepeat X-ray\nSymptom-free → 2 to 6 hours observation"},
{id:"px7",g:"T",p:1,s:"g",t:"Failed aspiration or a secondary pneumothorax: what do you do?",k:"Small-bore drain + admit\nAll secondary pneumothoraces are admitted\nLarge or symptomatic → small-bore drain"},
{id:"px8",g:"T",p:2,s:"g",t:"Chest drain: where is the site, and where do you cut to avoid the nerve and vessels?",k:"Site: fifth intercostal space, anterior to the mid-axillary line\nCut: incision above the lower rib → avoids the nerve and vessels\n(PCH guideline)"},
{id:"px9",g:"C",p:1,s:"g",t:"Chest drain: do you use routine suction, and why not?",k:"No routine suction\nRisk: re-expansion pulmonary oedema (NSW ACI)"},
{id:"px10",g:"C",p:1,s:"g",t:"Bubbling chest drain: can you clamp it, and where does the bottle go?",k:"Never clamp a bubbling drain\nBottle below chest level and upright"},
{id:"px11",g:"C",p:1,s:"g",t:"Chest drain stopped swinging and the patient is worse: what do you check and do?",k:"Check for kink, blockage, disconnection\n→ X-ray → call your senior\nA blocked tube can lead to tension"},
{id:"px12",g:"C",p:2,s:"g",t:"Ventilated patient with a sudden rise in airway pressure and low BP: what do you think of?",k:"Sudden rise in airway pressure + hypotension\n→ think tension pneumothorax"},
{id:"px13",g:"F",p:2,s:"g",t:"When do you remove a chest drain, and what if the leak persists?",k:"Lung up + no leak → remove\nPersistent leak for days → involve cardiothoracic surgery"},
{id:"px14",g:"F",p:2,s:"g",t:"After a pneumothorax: what advice do you give?",k:"Stop smoking\nRecurrence is common\nFlying and diving → per your respiratory team"}
], sg: [
{id:"pxs1",g:"T",p:3,s:"g",t:"Pneumothorax: what can oxygen do, and what is the caution in CO2 retainers?",k:"High-flow oxygen may speed resolution (NSW ACI); use the controlled target in CO2 retainers."}
]},
"acid-base-compensation": { items: [
{id:"ab7",g:"R",p:1,s:"k",t:"Reading a blood gas: what four questions do you ask, in order?",k:"1 → Is the pH low or high?\n2 → Did the CO2 or the bicarbonate move it?\n3 → Is the other side compensating as much as expected?\n4 → If metabolic acidosis → what is the anion gap?"},
{id:"ab8",dup:"ab4",g:"A",p:1,s:"k",t:"Metabolic acidosis: what pCO2 do you expect if the lungs are compensating?",k:"Expected pCO2 = 1.5 x bicarbonate + 8, give or take 2 mmHg (Winter formula)\n(Standard teaching formula.)"},
{id:"ab9",dup:"ab4",g:"A",p:2,s:"k",t:"Metabolic alkalosis: how much should the pCO2 rise?",k:"pCO2 rises about 0.7 mmHg for each 1 mmol/L rise in bicarbonate\n(Standard teaching.)"},
{id:"ab10",dup:"ab3",g:"A",p:2,s:"k",t:"Respiratory alkalosis: how much should bicarbonate fall per 10 mmHg fall in CO2, acute and chronic?",k:"Bicarbonate falls per 10 mmHg fall in CO2:\nAcute → about 2 mmol/L\nChronic → 4 to 5\n(Standard teaching.)"},
{id:"ab11",g:"A",p:1,s:"k",t:"The pCO2 is lower than expected in a metabolic acidosis: what does that mean, and name two causes?",k:"pCO2 lower than expected → second problem: respiratory alkalosis\nCauses: salicylate poisoning, sepsis, pain or anxiety"},
{id:"ab12",g:"A",p:1,s:"k",t:"The pCO2 is higher than expected in a metabolic acidosis: what does that mean?",k:"pCO2 higher than expected → added respiratory acidosis\nPatient is tiring or breathing is depressed\nWarning sign"},
{id:"ab13",g:"A",p:1,s:"k",t:"How do you calculate the anion gap, and what is normal?",k:"Anion gap = sodium − chloride − bicarbonate\nNormal about 8 to 12 (check your lab)\nLow albumin → lowers the normal value"},
{id:"ab1",g:"A",p:1,s:"n",t:"What sets the pH, and which buffers carry the acid load?",k:"pH depends on the ratio of bicarbonate to CO2 (Henderson-Hasselbalch)\n→ rises with bicarbonate; falls as CO2 (and H+) rises\nBicarbonate is the buffer you measure; haemoglobin, phosphate and proteins also buffer, and much buffering happens inside cells\nLungs → clear CO2\nKidney → keeps or excretes bicarbonate over hours to days"},
{id:"ab2",g:"A",p:1,s:"n",t:"Respiratory acidosis: how much should bicarbonate rise per 10 mmHg CO2, acute vs chronic, and why the difference?",k:"Bicarbonate rise per 10 mmHg CO2 rise:\nAcute → 1 mmol/L\nChronic (after a few days) → 4\nWhy: kidney needs days to hold bicarbonate → an acute CO2 rise drops the pH far more than the same rise in chronic COPD\n(Brandis, Acid-base Physiology; corrected from your note, which had 2 for chronic.)"},
{id:"ab3",g:"A",p:1,s:"n",t:"Respiratory alkalosis: how much should bicarbonate fall per 10 mmHg CO2, acute vs chronic?",k:"Bicarbonate falls per 10 mmHg fall in CO2:\nAcute → 2 mmol/L\nChronic (2 to 3 days) → 5\nAcute respiratory alkalosis: bicarbonate rarely below about 18 → lower means a metabolic acidosis as well\n(Brandis; corrected from your note, which had 3 and 4.)"},
{id:"ab4",g:"A",p:1,s:"n",t:"Metabolic acidosis and metabolic alkalosis: what CO2 do you expect from breathing compensation?",k:"Acidosis (Winter's): expected pCO2 = 1.5 x bicarbonate + 8 (plus or minus 2)\nAlkalosis: expected pCO2 = 0.7 x bicarbonate + 20 (plus or minus 5)\nCO2 outside the range → a second, respiratory problem\n(Brandis)"},
{id:"ab15",g:"T",p:1,s:"k",t:"A COPD patient on high-flow oxygen is drowsy with pH 7.24, pCO2 78 and bicarbonate 34: what is this, and what do you do first?",k:"Acute-on-chronic respiratory acidosis, worsened by too much oxygen\nTitrate oxygen to 88 to 92% (do not remove it)\nCall your senior\nRepeat the gas in 30 to 60 minutes\nNIV if pH stays below 7.35"},
{id:"ab14",dup:"ab6",g:"C",p:1,s:"k",t:"How can a normal pH hide two disorders, and how do you spot it?",k:"High-gap acidosis + metabolic alkalosis (e.g. vomiting) can cancel out → normal pH\nCompare rise in anion gap with fall in bicarbonate\nGap rose far more than bicarbonate fell → hidden alkalosis"},
{id:"ab5",g:"C",p:2,s:"n",t:"Why is compensation 'never complete', and what do clinicians mean by 'compensated'?",k:"Compensation moves pH towards normal, not all the way → pH still points to the primary problem\nOn the ward, 'compensated' loosely = pH in range, CO2 and bicarbonate abnormal\nFully normal pH + clearly abnormal CO2 and bicarbonate → look for two disorders"},
{id:"ab6",g:"C",p:1,s:"n",t:"High anion gap acidosis with a near-normal bicarbonate or a normal pH: how do you find a hidden metabolic alkalosis?",k:"High-gap acidosis + metabolic alkalosis (e.g. vomiting) can cancel out → normal pH\nDelta ratio = rise in AG / fall in HCO3\n1 to 2 → pure high anion gap acidosis\nAbove 2 → bicarbonate started high → metabolic alkalosis too (e.g. DKA with vomiting)\n0.4 to 0.8 → high and normal gap acidosis together\nBelow 0.4 → normal gap acidosis\n'Corrected bicarbonate' (measured HCO3 + extra anion gap): well above normal → alkalosis\n(LITFL)"},
{id:"ab16",g:"F",p:2,s:"k",t:"After acting on a blood gas: when do you repeat it?",k:"Usually 30 to 60 minutes after the change in treatment"}
], sg: []},
"metabolic-acidosis": { items: [
{id:"ma1",g:"R",p:1,s:"n",t:"Metabolic acidosis: what are the two ways it happens, with examples of each?",k:"Acid added (high anion gap): lactate, ketones, renal failure, toxins\nBicarbonate lost (normal anion gap):\nGut → diarrhoea, fistulas, drains, ileostomy (lower gut fluid is bicarbonate-rich)\nKidney → renal tubular acidosis, acetazolamide\nVomiting loses acid → alkalosis, not acidosis"},
{id:"ma6",dup:"ma4",g:"A",p:1,s:"k",t:"High anion gap acidosis: what are the main causes, and which first tests find them?",k:"Lactate → sepsis, shock\nKetones → diabetes, alcohol, starvation\nKidney failure\nToxins → methanol, ethylene glycol, salicylate, metformin\nFirst tests: lactate, ketones, creatinine, glucose, serum osmolality"},
{id:"ma7",dup:"ma5",g:"A",p:1,s:"k",t:"Normal anion gap acidosis: what are the main causes?",k:"Diarrhoea\nKidney tubular problems\nLarge load of 0.9% saline"},
{id:"ma2",g:"A",p:1,s:"n",t:"How do you calculate the anion gap, and why does it rise when acid is added but not when bicarbonate is lost?",k:"AG = Na − (Cl + HCO3)\nAbout 4 to 12 mmol/L without potassium with modern analysers (check whether your lab includes K and its range)\nAcid added → H+ uses up bicarbonate, its anion (lactate, ketone) is unmeasured → gap rises\nBicarbonate lost → chloride rises in its place → gap stays normal (hyperchloraemic)\n(LITFL)"},
{id:"ma3",g:"A",p:1,s:"n",t:"Low albumin: how do you correct the anion gap, and why does it matter in liver disease?",k:"Albumin is the main unmeasured anion\nCorrected AG = AG + 0.25 x (40 − albumin in g/L) (LITFL)\nWithout it, a high-gap acidosis can look normal in cirrhosis, sepsis, malnutrition → lactate from GI bleed or sepsis, or uraemia from hepatorenal syndrome, gets missed\n(Corrected from your note: 'x 3' works with albumin in g/dL; Australian labs report g/L.)"},
{id:"ma4",g:"A",p:1,s:"n",t:"High anion gap acidosis: which causes do you check for, and with which test?",k:"Lactate (sepsis, shock) → lactate level\nKetones (DKA, alcohol, starvation) → blood ketones, glucose\nRenal failure → urea, creatinine\nToxins:\nMethanol, ethylene glycol → osmolar gap; call Poisons Information 13 11 26\nSalicylate → level\nParacetamol, metformin, iron\nLITFL uses CAT MUDPILES; your PLUMSEEDS covers the same ground"},
{id:"ma5",g:"A",p:1,s:"n",t:"Normal anion gap acidosis: what are the causes, and how do you tell gut from kidney?",k:"Causes: gut loss (diarrhoea, fistulas, ileostomy, drains), renal tubular acidosis, hypoaldosteronism or Addison's, acetazolamide, large volumes of saline (chloride)\nGut vs kidney: urine anion gap (Na + K − Cl) → low = gut, raised = kidney\n(LITFL; corrected from your note: hypoaldosteronism and RTA give a normal anion gap, not a high one. DKA gives a high one.)"},
{id:"ma8",g:"T",p:1,s:"k",t:"Lactic acidosis from sepsis: what is the treatment?",k:"Treat the sepsis: cultures → antibiotics within the hour → measured fluid boluses → repeat lactate\nNot bicarbonate"},
{id:"ma9",g:"T",p:1,s:"k",t:"Alcoholic ketoacidosis: what do you give, and in what order?",k:"Thiamine first → then fluids with glucose → replace potassium and magnesium\nNo insulin: glucose is normal or low\n(Thiamine dose per hospital protocol.)"},
{id:"ma10",g:"T",p:2,s:"k",t:"Normal-gap acidosis from diarrhoea: what fluid, and what else do you replace?",k:"Balanced fluid such as Hartmann's → rather than large volumes of 0.9% saline (adds chloride)\nReplace potassium"},
{id:"ma11",g:"T",p:1,s:"k",t:"Acidosis with a kidney injury in a patient on metformin: what do you do with the metformin?",k:"Stop it"},
{id:"ma12",g:"C",p:1,s:"k",t:"Why is bicarbonate rarely first-line in metabolic acidosis, and how is it given if a senior wants it?",k:"Why rarely first-line: does not fix lactate or ketones, can lower potassium, raises CO2\nIf a senior wants it: 50 mL of 8.4% slowly over 5 to 15 minutes → never a 100 mL push\nMainly considered in severe acidosis with kidney injury or high potassium\n(No Australian threshold was verified.)"},
{id:"ma13",g:"C",p:1,s:"k",t:"An unexplained high-gap acidosis or suspected toxic alcohol: who do you call?",k:"Your senior\nPoisons Information Centre 13 11 26"},
{id:"ma14",g:"C",p:1,s:"k",t:"Metabolic acidosis: which findings mean you call your registrar now?",k:"pH under 7.2\nLactate above 4\nShock not responding to the first boluses\nPatient tiring (rising pCO2)\n(Victoria: Adult Retrieval Victoria coordinates transfer of critically ill adults and gives phone advice, 1300 36 86 61. Confirm who calls at GV Health.)"}
], sg: []},
"metabolic-alkalosis": { items: [
{id:"mk6",g:"R",p:2,s:"k",t:"Severe metabolic alkalosis: what symptoms and signs can it cause?",k:"Tetany and cramps (ionised calcium falls)\nWeakness\nArrhythmias\nSlow breathing"},
{id:"mk1",g:"R",p:1,s:"n",t:"Metabolic alkalosis: what are the ways it happens, with examples?",k:"Acid lost: vomiting or NG aspirate; urine (diuretics, mineralocorticoid excess)\nH+ shifted into cells: low potassium\nBicarbonate gained: given directly, or made by the liver from lactate or citrate (large volumes of Hartmann's, massive transfusion)\nFast correction of chronic CO2 retention\n(Standard teaching.)"},
{id:"mk7",g:"A",p:1,s:"k",t:"Metabolic alkalosis: what does a urine chloride under 20 mmol/L mean, and what are the causes?",k:"Urine chloride under 20 → chloride-responsive (volume depleted)\nCauses: vomiting, nasogastric losses, past diuretic use\n(Usual cut-off; standard teaching.)"},
{id:"mk8",g:"A",p:1,s:"k",t:"Metabolic alkalosis: what does a urine chloride over 20 mmol/L mean, and what are the causes?",k:"Urine chloride over 20 → chloride-resistant\nCauses: hyperaldosteronism, Cushing syndrome, severe potassium loss\nOr a diuretic taken in the last day or two → result misleading"},
{id:"mk2",g:"A",p:1,s:"n",t:"Why do vomiting and diuretics keep a metabolic alkalosis going, and what fixes it?",k:"Lose volume and chloride → kidney holds sodium under aldosterone\nSodium reaching the collecting duct + high aldosterone → drives potassium and H+ into urine\nLow chloride → kidney cannot get rid of the extra bicarbonate\nLow potassium → H+ moves into cells → worsens it\nFix: saline + potassium\n(Corrected from your note: diuretics do not shift sodium into cells; they lose sodium, chloride, potassium and H+ in the urine.)"},
{id:"mk9",g:"T",p:1,s:"k",t:"Chloride-responsive alkalosis: what is the treatment?",k:"0.9% saline → chloride and volume\nPotassium and magnesium replacement\nReplace ongoing nasogastric losses while the cause is treated"},
{id:"mk10",g:"T",p:1,s:"k",t:"Chloride-resistant alkalosis with hypertension and low potassium: what do you do?",k:"Replace potassium\nCheck magnesium\nInvestigate excess aldosterone (aldosterone and renin, cortisol) with endocrinology\nSaline does not help and can raise the BP"},
{id:"mk11",g:"T",p:2,s:"k",t:"Alkalosis in an overloaded heart failure patient on high-dose diuretics: what are the options?",k:"Reduce the diuretic if the oedema allows\nReplace potassium\nSenior may add acetazolamide\nDo not give saline"},
{id:"mk12",g:"C",p:1,s:"k",t:"Metabolic alkalosis: which fluids and drugs do you avoid?",k:"Bicarbonate\nMore loop diuretic\nHypotonic fluids such as glucose 5%"},
{id:"mk3",g:"C",p:2,s:"n",t:"How does excess mineralocorticoid (Conn's, steroids, liquorice) cause alkalosis and low potassium?",k:"Aldosterone → collecting duct reabsorbs sodium, secretes potassium (principal cells) and H+ (intercalated cells)\nToo much → both lost in urine → low potassium + metabolic alkalosis, usually high BP\nSaline does not correct it (chloride-resistant)\n(Standard teaching.)"},
{id:"mk4",g:"C",p:2,s:"n",t:"Post-hypercapnic alkalosis: what is it, and why only after chronic CO2 retention?",k:"Chronic CO2 retention → kidney builds up high bicarbonate\nCO2 brought down quickly (NIV or ventilator) → bicarbonate stays high for days → alkalosis\nAcute retention → bicarbonate never rose much → does not happen\n(Answers your question about chronic only.)"},
{id:"mk5",g:"C",p:3,s:"n",t:"Why can feeding after a period of starvation cause a mild alkalosis?",k:"Fasting → ketoacids build up, body keeps their anions\nCarbohydrate given → anions metabolised → regenerates bicarbonate → pH can overshoot into mild alkalosis\n(Standard teaching; I could not check it against an Australian source.)"},
{id:"mk13",g:"F",p:2,s:"k",t:"Metabolic alkalosis: when do you call your registrar?",k:"pH over 7.55\nECG changes or tetany\nHypertension + low potassium + high urine chloride"}
], sg: []},
"hyperkalemia": { items: [
{id:"hk5",g:"R",p:1,s:"k",t:"Hyperkalaemia: what potassium levels are mild, moderate and severe?",k:"Mild: 5.5 to 5.9\nModerate: 6.0 to 6.4\nSevere: 6.5 mmol/L and above\nAny ECG change → emergency whatever the number\n(NSW SESLHD.)"},
{id:"hk6",g:"R",p:1,s:"k",t:"Hyperkalaemia: what are the ECG changes, in the order they appear?",k:"Tall peaked T waves\n→ long PR, flat P waves\n→ wide QRS\n→ sine wave\n→ VF or asystole"},
{id:"hk1",g:"R",p:1,s:"n",t:"Where is the body's potassium, and what moves it into cells?",k:"About 98% is inside cells; plasma holds only a little (your note: about 12 mmol) → small shifts change the level a lot\nNa-K ATPase pumps potassium in, sodium out\nInsulin and beta-2 agonists switch it on → why insulin-dextrose and salbutamol lower potassium"},
{id:"hk2",g:"R",p:1,s:"n",t:"Which acidoses push potassium out of cells, and which barely do?",k:"Mineral (non-anion gap) acidosis → shifts potassium out: H+ enters cells without its anion, potassium leaves to keep charge balanced\nOrganic acids (lactate, ketones) → move with their anion → shift little potassium\nAlkalosis → opposite, lowers potassium\n(Standard teaching.)"},
{id:"hk7",g:"A",p:1,s:"k",t:"A high potassium result with a normal ECG and no risk factors: what do you check before treating?",k:"Was the sample haemolysed or delayed?\nRepeat urgently (a blood gas gives a fast answer)\nDo an ECG"},
{id:"hk8",g:"A",p:2,s:"k",t:"Hyperkalaemia: which drugs do you look for on the chart?",k:"ACE inhibitors, ARBs\nSpironolactone and other potassium-sparing diuretics\nTrimethoprim\nNSAIDs\nPotassium supplements"},
{id:"hk3",g:"A",p:1,s:"n",t:"How does the kidney excrete potassium, and which two things does it need?",k:"Where: principal cells of the collecting duct\nSodium reabsorbed → tubule negative → pulls potassium into urine\nAldosterone adds sodium channels and drives this\nSo potassium loss needs both distal sodium delivery and aldosterone\nNormally they balance (high salt intake lowers aldosterone) → potassium steady"},
{id:"hk9",g:"T",p:1,s:"k",t:"Hyperkalaemia with ECG changes: what do you give first, what dose and how fast, and what does it not do?",k:"Calcium gluconate 10% 10 mL (2.2 mmol) IV over 2 to 3 minutes, on a monitor\nRepeat ECG after 5 to 10 minutes → repeat the dose if still abnormal\nProtects the heart, does not lower the potassium\n(NSW SESLHD and Queensland Health.)"},
{id:"hk10",g:"T",p:1,s:"k",t:"Hyperkalaemia: what are the insulin and glucose regimens in NSW and Queensland?",k:"NSW SESLHD: 10 units Actrapid in 50 mL of glucose 50% over 30 minutes\nQueensland Health: 5 to 10 units with 50 mL of glucose 50% over 5 minutes → 5 units in kidney failure or under 50 kg\nUse your own hospital protocol"},
{id:"hk11",g:"T",p:1,s:"k",t:"After insulin and glucose for hyperkalaemia: how do you monitor the glucose, and why?",k:"Check before the dose\nThen every 30 minutes for 2 hours (NSW) or at least hourly for 6 hours (Queensland)\nHypoglycaemia can come late, especially in kidney failure"},
{id:"hk12",g:"T",p:2,s:"k",t:"Hyperkalaemia: what is the salbutamol dose, and what is its role?",k:"10 mg nebulised (Queensland Health)\nExtra shifter added to insulin, not a replacement"},
{id:"hk13",g:"T",p:2,s:"k",t:"Hyperkalaemia: when is sodium bicarbonate used, and how is it given?",k:"Only when there is a metabolic acidosis\n50 mL of 8.4% IV over 5 to 15 minutes\nNever a rapid large push\n(NSW SESLHD.)"},
{id:"hk14",g:"T",p:1,s:"k",t:"Hyperkalaemia: which treatments actually remove potassium from the body?",k:"Binding resin: Resonium A 15 g orally, up to three or four times a day in NSW\nDialysis\nStop the cause\nCalcium and insulin only protect and shift"},
{id:"hk15",g:"C",p:1,s:"k",t:"Hyperkalaemia: why must you recheck after treatment, and how often?",k:"Insulin wears off in a few hours → potassium rebounds\nRecheck every 2 hours (NSW), or hourly if severe (Queensland)\nUntil below 5.5"},
{id:"hk16",g:"C",p:1,s:"k",t:"Hyperkalaemia: who needs a call to the renal team or dialysis?",k:"ECG changes\nPotassium 6.5 or more that does not respond\nPasses no urine\nAny dialysis patient who has missed a session"},
{id:"hk4",g:"C",p:1,s:"n",t:"Why do ACE inhibitors, ARBs and spironolactone raise potassium in CKD and heart failure?",k:"CKD, heart failure, cirrhosis, volume depletion → less sodium reaches the collecting duct → potassium excretion depends on high aldosterone\nACE inhibitor, ARB, spironolactone block aldosterone → support removed → potassium rises\nCheck potassium and creatinine after starting or increasing these drugs"},
{id:"hk17",g:"F",p:2,s:"k",t:"Hyperkalaemia from drugs in AKI: when do the drugs restart?",k:"Restart only when potassium and creatinine are stable\nOften at a lower dose\nCheck potassium a few days after restarting"}
], sg: []},
"diabetic-ketoacidosis": { items: [
{id:"dk1",g:"A",p:1,s:"n",t:"DKA: why can potassium be high, normal or low, and when must you not start insulin?",k:"Total body potassium is low (lost in urine)\nInsulin lack + high glucose hold potassium outside cells → blood level can look normal or high\nInsulin drives it back in → level falls fast\nNSW ACI: no insulin infusion until K is above 3.5 mmol/L\nReplace potassium by level; check every 1 to 2 hours on a monitor\n(Corrected from your note: ketoacids shift little potassium; the high level comes mainly from insulin lack and high glucose.)"}
], sg: []},
"hypokalemia": { items: [
{id:"hy5",g:"R",p:1,s:"k",t:"Hypokalaemia: what levels are mild, moderate and severe, and what makes any level urgent?",k:"Mild: 3.0 to 3.4\nModerate: 2.5 to 2.9\nSevere: below 2.5 mmol/L\nECG changes, symptoms or digoxin → urgent at any level\n(Standard teaching.)"},
{id:"hy6",g:"R",p:1,s:"k",t:"Hypokalaemia: what are the ECG changes?",k:"Flat T waves\n→ ST depression, prominent U waves\n→ ectopics, atrial or ventricular arrhythmias including torsades"},
{id:"hy1",g:"R",p:1,s:"n",t:"Low potassium: what are the three groups of causes, and which other level do you check?",k:"Low intake → rarely enough on its own; usually with vomiting or diuretics\nShift into cells\nLosses → kidney, gut, skin\nCheck magnesium → low magnesium keeps potassium being lost in urine, hard to correct\n(LITFL)"},
{id:"hy2",g:"R",p:1,s:"n",t:"Which causes shift potassium into cells?",k:"Insulin (including refeeding syndrome)\nBeta-2 agonists → salbutamol in asthma or COPD, beta-agonist tocolytics\nAlkalosis\nFast new cell production → starting B12 or folate for megaloblastic anaemia\n(LITFL for the first three; the B12 point is standard teaching, not on the Australian pages I checked.)"},
{id:"hy7",g:"A",p:1,s:"k",t:"Hypokalaemia: why does digoxin matter?",k:"Low potassium → raises risk of digoxin toxicity and arrhythmia\nTell your registrar → monitor the ECG"},
{id:"hy3",g:"A",p:2,s:"n",t:"Why does vomiting cause low potassium when gastric fluid holds little potassium?",k:"The loss is mainly in the urine, not the gastric fluid\nAlkalosis → bicarbonate (with sodium) goes down to the collecting duct\nVolume loss → raises aldosterone\nTogether → drive potassium out\nYour note was right that the gastric loss itself is small\n(Standard teaching.)"},
{id:"hy8",g:"T",p:1,s:"k",t:"Hypokalaemia: when is oral replacement enough, and when do you go to IV?",k:"Oral → mild or moderate, working gut, normal ECG\nIV → severe, ECG changes, symptoms, or cannot take or absorb tablets\n(Oral dose per your hospital protocol; not checked here.)"},
{id:"hy9",g:"T",p:1,s:"k",t:"IV potassium on a general ward: what concentration and rate, and what are the two things you never do?",k:"10 mmol in 100 mL over 1 hour through a peripheral line, premixed bag\nNever a push\nNever add it to a bag already running\n(NSW potassium guidance.)"},
{id:"hy10",g:"T",p:1,s:"k",t:"IV potassium faster than 10 mmol an hour: what does it need?",k:"Faster than 10 mmol an hour → monitored setting with continuous ECG\n+ senior approval"},
{id:"hy11",g:"T",p:1,s:"k",t:"Hypokalaemia that will not correct: what do you check and replace?",k:"Check and replace magnesium\nLow magnesium → kidney keeps losing potassium\n(Dose per hospital protocol.)"},
{id:"hy12",g:"C",p:2,s:"k",t:"Replacing potassium in kidney failure: what is the risk?",k:"Risk: overshooting into hyperkalaemia\n→ replace in smaller amounts, recheck more often"},
{id:"hy4",g:"C",p:2,s:"n",t:"When do aldosterone and distal sodium together cause a big potassium loss, and how does primary aldosteronism fit?",k:"Big potassium loss when both are high at once:\nDiuretic (more sodium downstream) + high aldosterone (volume loss, heart failure, or primary aldosteronism)\nPrimary aldosteronism (Conn's adenoma or bilateral adrenal hyperplasia) → raises aldosterone by itself → retained sodium expands volume → body sends more sodium downstream → potassium keeps being lost\nLook for high BP with low potassium\n(LITFL lists these causes.)"},
{id:"hy13",g:"F",p:1,s:"k",t:"Hypokalaemia: when do you recheck, and what else must be fixed?",k:"Recheck after each 20 to 40 mmol, and the next morning\nFix the cause: review diuretics, treat vomiting, diarrhoea or high-output stoma"}
], sg: []},
"acute-kidney-injury": { items: [
{id:"ak1",g:"R",p:1,s:"k",t:"AKI: which two measurements define it, and what must you compare the creatinine with?",k:"Rise in creatinine or fall in urine output → either counts\nCompare with the patient's baseline creatinine, not the lab range\n(KDIGO approach; the exact Australian wording was not checked.)"},
{id:"ak2",g:"R",p:1,s:"k",t:"AKI staging by creatinine: what multiple of baseline marks stage 1, 2 and 3?",k:"Stage 1: 1.5 to 1.9 times baseline (or rise of 26.5 micromol/L or more within 48 hours)\nStage 2: 2 to 2.9 times\nStage 3: 3 times or more, creatinine of 354 micromol/L or more, or starting dialysis\n(Standard KDIGO teaching, not checked against the Australian text.)"},
{id:"ak3",g:"R",p:2,s:"k",t:"AKI staging by urine output: what output for how long marks each stage?",k:"Stage 1: under 0.5 mL/kg/h for 6 to 12 hours\nStage 2: under 0.5 mL/kg/h for 12 hours or more\nStage 3: under 0.3 mL/kg/h for 24 hours, or no urine for 12 hours\n(Standard KDIGO teaching.)"},
{id:"ak4",g:"A",p:1,s:"k",t:"AKI: what are the three groups of causes, and one common ward example of each?",k:"Pre-renal (low flow to kidney) → dehydration, sepsis, heart failure\nIntrinsic (damage in kidney) → acute tubular necrosis, nephrotoxic drugs, glomerulonephritis\nPost-renal (blocked outflow) → urinary retention, stones, blocked catheter"},
{id:"ak5",g:"A",p:1,s:"k",t:"AKI: which three drugs together classically cause pre-renal AKI in a dry patient?",k:"ACE inhibitor or ARB + diuretic + NSAID\n→ the 'triple whammy'"},
{id:"ak6",g:"A",p:1,s:"k",t:"AKI: which bedside checks do you do in the first hour?",k:"Volume status: BP lying and standing, mucous membranes, JVP, oedema\nDrug chart review\nBladder scan\nUrine dipstick for blood and protein\nUrine output chart"},
{id:"ak7",g:"A",p:2,s:"k",t:"AKI: what does blood and protein on the dipstick suggest, and who do you tell?",k:"Blood and protein → intrinsic cause such as glomerulonephritis\n→ tell your registrar and the renal team early"},
{id:"ak8",g:"A",p:2,s:"k",t:"AKI: when do you ask for a renal tract ultrasound?",k:"When obstruction is possible or cause unclear → usually within 24 hours\nInfected, obstructed kidney suspected → sooner"},
{id:"ak9",g:"T",p:1,s:"k",t:"Pre-renal AKI in a dry patient: how do you give fluid?",k:"Measured boluses of 250 to 500 mL\nReassess after each: BP, urine output, signs of overload\nStop when euvolaemic"},
{id:"ak10",g:"T",p:1,s:"k",t:"AKI: which drugs do you withhold or adjust?",k:"Withhold: ACE inhibitors, ARBs, diuretics (unless overloaded), NSAIDs, metformin\nAvoid if you can: aminoglycosides, IV contrast\nAdjust the dose of renally cleared drugs"},
{id:"ak11",g:"T",p:1,s:"k",t:"AKI from urinary retention: what do you do, and what do you watch for afterwards?",k:"Bladder scan → insert catheter, record volume drained\nThen chart hourly urine output\nWatch for large post-obstructive diuresis → dehydration, electrolyte loss"},
{id:"ak12",g:"C",p:1,s:"k",t:"AKI: which complications need an urgent call to your registrar or the renal team?",k:"Potassium 6.5 or more, or ECG changes\nPulmonary oedema not responding\nSevere acidosis\nUraemic signs (pericarditis, confusion)\nInfected, obstructed kidney"},
{id:"ak13",g:"C",p:2,s:"k",t:"AKI: why is furosemide the wrong treatment for low urine output in a dry patient?",k:"Diuretic does not treat the cause\nDry or hypotensive patient → lowers BP and kidney blood flow further"},
{id:"ak14",g:"F",p:2,s:"k",t:"AKI: what do you do daily while it recovers, and when do the withheld drugs restart?",k:"Daily: creatinine, potassium, fluid balance, weight\nRestart ACE inhibitors and diuretics only once creatinine has settled → often at a lower dose → repeat blood test afterwards\nWrite the drug hold and restart plan in the notes"}
], sg: []},
"hyponatremia": { items: [
{id:"hn1",g:"R",p:1,s:"k",t:"Hyponatraemia: what levels are mild, moderate and severe, and which symptoms are an emergency?",k:"Mild: 130 to 134\nModerate: 125 to 129\nSevere: below 125 mmol/L\nSeizure or coma → emergency whatever the number"},
{id:"hn2",g:"A",p:1,s:"k",t:"Hyponatraemia: which tests sort the type?",k:"Serum osmolality → confirms a true low-sodium state\nUrine osmolality + urine sodium\nCortisol + thyroid function → before calling it SIADH"},
{id:"hn3",g:"A",p:1,s:"k",t:"Hyponatraemia: what are the three volume groups, with a cause of each?",k:"Dry (hypovolaemic) → vomiting, diarrhoea, diuretics\nNormal volume → SIADH, adrenal insufficiency, hypothyroidism\nWet (hypervolaemic) → heart failure, cirrhosis, kidney disease"},
{id:"hn4",g:"A",p:2,s:"k",t:"Hyponatraemia: which common drugs cause it?",k:"Thiazides\nSSRIs\nCarbamazepine\nProton pump inhibitors"},
{id:"hn5",g:"A",p:2,s:"k",t:"What urine results fit SIADH?",k:"Euvolaemic patient\nUrine concentrated: osmolality inappropriately high (usually over 100 mmol/kg)\nUrine sodium not low (usually over 30 mmol/L)\nNormal cortisol and thyroid function\n(Standard teaching.)"},
{id:"hn6",g:"T",p:1,s:"k",t:"Hyponatraemia with a seizure or coma: what do you give, how fast, and how often can you repeat it?",k:"Hypertonic saline 3%: 150 mL IV over 20 minutes\nCheck sodium after each bolus\nRepeat up to twice\n(NSW SESLHD.)"},
{id:"hn7",g:"T",p:1,s:"k",t:"Severe symptomatic hyponatraemia: what rise are you aiming for in the first hour, and then what?",k:"Aim: about 5 mmol/L rise in the first hour → then stop the hypertonic saline\nGoal is to stop the seizure, not reach a normal sodium\n(NSW SESLHD.)"},
{id:"hn8",g:"T",p:1,s:"k",t:"SIADH: what is the treatment, and why is 0.9% saline the wrong fluid?",k:"Fluid restriction + treat the cause\n0.9% saline is wrong: kidney passes the salt, keeps the water → sodium can fall further\n(Restriction volume per hospital protocol; not checked here.)"},
{id:"hn9",g:"T",p:2,s:"k",t:"Hypovolaemic hyponatraemia: what fluid, and what do you watch for once the volume is restored?",k:"0.9% saline\nOnce volume is back → kidney passes dilute urine → sodium can rise very fast"},
{id:"hn10",g:"T",p:1,s:"k",t:"Any hyponatraemia: which IV fluids do you stop?",k:"Stop hypotonic fluids: glucose 5%, 0.45% saline\nThey are free water"},
{id:"hn11",g:"C",p:1,s:"k",t:"Hyponatraemia: what is the maximum rise in sodium in 24 hours, and in whom is it lower?",k:"No more than 10 mmol/L in 24 hours\n8 in high-risk patients: alcohol dependence, malnutrition, liver disease, low potassium\n(NSW SESLHD.)"},
{id:"hn12",g:"C",p:1,s:"k",t:"What is the danger of correcting a low sodium too fast, and when does it show?",k:"Osmotic demyelination\nWeakness, speech and swallowing problems, locked-in state → appears days later\nCannot be reversed"},
{id:"hn13",g:"C",p:1,s:"k",t:"During sodium correction: how often do you check the sodium, and which bedside sign warns of overcorrection?",k:"Every 2 to 4 hours (and after each bolus in a severe case)\nWarning sign: sudden large output of dilute urine → sodium about to rise fast"},
{id:"hn14",g:"F",p:2,s:"k",t:"The sodium is rising too fast: what do you do?",k:"Stop the hypertonic saline\nCheck sodium hourly\nCall your registrar\nDesmopressin and glucose 5% can bring it back → senior decision\n(Regimen not checked here.)"}
], sg: []},
"hypernatremia": { items: [
{id:"hx1",g:"R",p:1,s:"k",t:"Hypernatraemia: what are the three groups of causes?",k:"Water loss with poor intake → dehydration, fever, cannot reach a drink\nWater loss through the kidney → high glucose, diabetes insipidus\nSalt gain → hypertonic saline or bicarbonate (rare)"},
{id:"hx2",g:"R",p:2,s:"k",t:"Hypernatraemia: what levels are mild, moderate and severe?",k:"Mild: 146 to 150\nModerate: 151 to 159\nSevere: 160 mmol/L and above\n(Standard teaching.)"},
{id:"hx3",g:"A",p:1,s:"k",t:"Hypernatraemia: what do you assess at the bedside first?",k:"Shocked? BP, pulse\nConscious level\nUrine volume and concentration"},
{id:"hx8",g:"A",p:1,s:"k",t:"What findings suggest diabetes insipidus?",k:"High sodium + very large output of dilute urine\nOver 3 L a day or about 200 mL an hour\nUrine osmolality below 300 mmol/kg"},
{id:"hx9",g:"A",p:2,s:"k",t:"Diabetes insipidus: what are the causes of the central and nephrogenic types?",k:"Central → head injury, pituitary surgery\nNephrogenic → lithium, hypercalcaemia"},
{id:"hx4",g:"T",p:1,s:"k",t:"Hypernatraemia with shock: what fluid comes first?",k:"0.9% saline in boluses until perfusion is restored\nFree water comes after"},
{id:"hx5",g:"T",p:1,s:"k",t:"Hypernatraemia, not shocked: how do you replace the water?",k:"Oral or enteral water if the patient can take it\nOtherwise glucose 5% IV, at a rate agreed with your senior"},
{id:"hx10",g:"T",p:1,s:"k",t:"Central diabetes insipidus: what is the treatment, and who decides?",k:"Water replacement + hourly urine output + frequent sodium checks\nDesmopressin treats the cause → dose decided with your registrar and the endocrine or surgical team\nNever restrict fluids"},
{id:"hx6",g:"C",p:1,s:"k",t:"Chronic hypernatraemia: how fast can the sodium fall, and what is the danger of going faster?",k:"No more than 10 mmol/L in 24 hours (about 0.5 an hour)\nFaster fall → water moves into brain cells → cerebral oedema, seizures\n(Standard teaching; not checked against an Australian source.)"},
{id:"hx7",g:"C",p:1,s:"k",t:"Treating hypernatraemia: how often do you check the sodium?",k:"Every 4 to 6 hours\nMore often if it is falling fast"},
{id:"hx11",g:"F",p:2,s:"k",t:"Hypernatraemia: what do you fix besides the sodium?",k:"Fix the cause: infection, high glucose, drugs\nAnd the reason the patient could not drink"}
], sg: []},
"hypercalcemia": { items: [
{id:"hc1",g:"R",p:1,s:"k",t:"Hypercalcaemia: which calcium value do you use, and what levels are mild, moderate and severe?",k:"Use the corrected (albumin-adjusted) calcium\nMild: 2.6 to 2.9\nModerate: 3.0 to 3.4\nSevere: 3.5 mmol/L and above\n(UK Society for Endocrinology; no Australian source checked.)"},
{id:"hc2",g:"R",p:1,s:"k",t:"Hypercalcaemia: what are the symptoms and the ECG change?",k:"Symptoms: thirst, polyuria, constipation, nausea, abdominal pain, confusion\nECG: short QT"},
{id:"hc3",g:"A",p:1,s:"k",t:"Hypercalcaemia: what are the two commonest causes, and which drugs contribute?",k:"Cancer → commonest in hospital\nPrimary hyperparathyroidism → commonest in the community\nDrugs: thiazides, calcium and vitamin D supplements, lithium"},
{id:"hc4",g:"A",p:1,s:"k",t:"Hypercalcaemia: what does the PTH tell you?",k:"High or normal PTH → primary hyperparathyroidism\nLow (suppressed) PTH → cancer or vitamin D excess"},
{id:"hc5",g:"A",p:2,s:"k",t:"Hypercalcaemia: which other tests look for the cause?",k:"Calcium, albumin, phosphate, kidney function\nSerum protein electrophoresis + free light chains (myeloma)\nChest X-ray"},
{id:"hc6",g:"T",p:1,s:"k",t:"Moderate or severe hypercalcaemia: what is the first treatment, and how much?",k:"0.9% saline IV, about 4 to 6 L over 24 hours\nCheck for overload after each litre\nLess in heart or kidney failure\n(UK Society for Endocrinology.)"},
{id:"hc7",g:"T",p:1,s:"k",t:"Hypercalcaemia: which drugs do you stop?",k:"Thiazides\nCalcium\nVitamin D"},
{id:"hc8",g:"T",p:1,s:"k",t:"Hypercalcaemia: what drug lowers the calcium after fluids, at what dose and rate, and how long does it take to work?",k:"Zoledronic acid 4 mg IV over at least 15 minutes\nAfter rehydration; dose adjusted for kidney function\nWorks in 2 to 4 days\n(UK Society for Endocrinology.)"},
{id:"hc9",g:"T",p:2,s:"k",t:"Hypercalcaemia: when are steroids used?",k:"Lymphoma, myeloma, sarcoid, vitamin D excess → steroids\nPrimary hyperparathyroidism → not for steroids"},
{id:"hc10",g:"C",p:1,s:"k",t:"Hypercalcaemia: why is furosemide not used first?",k:"Patient is dry → loop diuretic worsens dehydration and kidney injury\nUse only for fluid overload"},
{id:"hc11",g:"F",p:2,s:"k",t:"Mild hypercalcaemia with a raised PTH: what is the plan?",k:"Stop contributing drugs\nOral fluids\nRepeat calcium\nRefer to endocrinology or surgery for primary hyperparathyroidism\nNo bisphosphonate or large-volume saline"}
], sg: []},
"nephrolithiasis": { items: [
{id:"st1",g:"R",p:1,s:"k",t:"Renal colic: what is the typical picture?",k:"Sudden loin pain → spreads to the groin, in waves\nCannot lie still\nNausea and vomiting\nBlood on urine dipstick"},
{id:"st2",g:"R",p:1,s:"k",t:"Suspected renal colic: which other diagnoses must you not miss, and in whom?",k:"Man over 60, first episode → leaking abdominal aortic aneurysm\nWoman → ectopic pregnancy, ovarian torsion\nYoung man → testicular torsion\nAppendicitis"},
{id:"st3",g:"A",p:1,s:"k",t:"Renal colic: which tests do you send?",k:"Urine dipstick and culture\nCreatinine and electrolytes\nFBC and CRP\nPregnancy test if she could be pregnant"},
{id:"st4",g:"A",p:1,s:"k",t:"Renal colic: what is the usual scan, and what do you use in pregnancy?",k:"CT KUB without contrast\nPregnancy → ultrasound"},
{id:"st5",g:"T",p:1,s:"k",t:"Renal colic: what analgesia do you use first, and what do you add?",k:"NSAID if kidney function normal and no contraindication + paracetamol\nPain not controlled → IV morphine in small steps\nAdd an antiemetic\n(Drug doses per hospital protocol; not checked here.)"},
{id:"st6",g:"C",p:1,s:"k",t:"A stone with fever: what is the diagnosis until proven otherwise, and what do you do?",k:"Infected, obstructed kidney until proven otherwise → emergency\nBlood and urine cultures → IV antibiotics → fluids\nUrgent call to urology → drain with stent or nephrostomy"},
{id:"st7",g:"C",p:1,s:"k",t:"Renal colic: when is an NSAID the wrong choice?",k:"Kidney injury\nSepsis\nThe usual contraindications"},
{id:"st8",g:"F",p:1,s:"k",t:"A stone on CT: who can go home?",k:"Pain controlled on tablets\nEating and drinking, afebrile\nNormal kidney function\nSmall stone (about 5 mm or less often passes)"},
{id:"st9",g:"F",p:1,s:"k",t:"Discharge with a kidney stone: what does the patient take away?",k:"Analgesia\nUrine strainer\nUrology follow-up\nReturn for: fever, uncontrolled pain, vomiting, no urine"},
{id:"st10",g:"F",p:2,s:"k",t:"A stone on CT: who needs a urology referral before discharge?",k:"Stone larger than about 7 to 10 mm\nSolitary kidney\nKidney injury\nPain that cannot be controlled\nAny sign of infection (urgent)"}
], sg: []},
"uti-and-pyelonephritis": { items: [
{id:"ut1",g:"R",p:1,s:"k",t:"An older patient is confused with a positive dipstick but no fever or urinary symptoms: is this a UTI, and what do you do?",k:"Usually asymptomatic bacteriuria, not a UTI → do not treat it\nLook for the real cause of the confusion: glucose, infection elsewhere, pain, constipation, urinary retention, new drugs, low sodium"},
{id:"ut2",g:"R",p:1,s:"k",t:"Who is treated for asymptomatic bacteriuria?",k:"Pregnant women\nPatients about to have a urological procedure that breaches the lining\nNo one else"},
{id:"ut3",g:"R",p:1,s:"k",t:"How do you tell cystitis from pyelonephritis?",k:"Cystitis: dysuria, frequency, urgency, suprapubic pain, no fever\nPyelonephritis: fever, rigors, loin pain, vomiting, feeling unwell"},
{id:"ut4",g:"R",p:2,s:"k",t:"What makes a UTI 'complicated'?",k:"Male patient\nPregnancy\nCatheter\nDiabetes\nKidney disease\nStones or obstruction"},
{id:"ut5",g:"A",p:1,s:"k",t:"Pyelonephritis: which tests do you take before the first antibiotic dose?",k:"Midstream urine culture\nBlood cultures if febrile\nCreatinine\nPregnancy test if she could be pregnant\nDo not delay antibiotics in sepsis"},
{id:"ut6",g:"T",p:1,s:"k",t:"Pyelonephritis: who gets oral antibiotics and who gets IV?",k:"Oral → mild and able to keep tablets down\nIV → vomiting, septic or otherwise severe\nChoose by the Therapeutic Guidelines and local resistance\n(Drugs and doses not checked here.)"},
{id:"ut7",g:"T",p:2,s:"k",t:"Why is nitrofurantoin not used for pyelonephritis?",k:"Does not reach effective levels in kidney tissue\nFor cystitis only"},
{id:"ut9",g:"C",p:1,s:"k",t:"Pyelonephritis not improving after 48 to 72 hours of the right antibiotic: what do you do?",k:"Image the kidneys (ultrasound or CT) → stone, obstruction or abscess\nTell your seniors"},
{id:"ut10",g:"C",p:2,s:"k",t:"A UTI in a man: what is different?",k:"Complicated by definition\nAlways send a culture\nThink of the prostate\nTreat for longer"},
{id:"ut8",g:"F",p:1,s:"k",t:"Pyelonephritis on IV antibiotics: when do you switch to oral?",k:"When afebrile, eating and improving\nAnd culture sensitivities are known"},
{id:"ut11",g:"F",p:2,s:"k",t:"UTI: when do you call your registrar?",k:"Sepsis (low BP, fast pulse, lactate above 2)\nPregnancy\nTransplant\nSuspected obstructed kidney\nNo improvement after 48 hours"}
], sg: []}
};
